1567		ctx context.Context,
1568		repo string,
1569		q, sparseQuery searchQuery,
1570		options SearchOptions,
1571		preindexedSnapshot ProviderSnapshot,
1572		preindexCacheHit bool,
1573	) (searchFileSelection, error) {
1574		source, err := prepareSource(ctx, repo, ProviderSnapshotOptions{
1575			NoNetwork:    true,
1576			Worktree:     options.Worktree,
1577			IgnoreFiles:  options.IgnoreFiles,
1578			IncludeFiles: options.IncludeFiles,
1579		})
1580		if err != nil {
1581			return searchFileSelection{}, err
1582		}
1583		if source.close != nil {
1584			defer source.close()
1585		}
1586		selection := searchFileSelection{
1587			repoRoot:                  source.absRepo,
1588			commit:                    source.commit,
1589			tree:                      source.tree,
1590			warnings:                  append([]ProviderWarning{}, source.warnings...),
1591			filesScanned:              len(source.paths),
1592			preselectionBackend:       "inventory",
1593			preselectionPasses:        1,
1594			preselectionFilesExamined: len(source.paths),
1595			sparseFiles:               append([]string(nil), source.paths...),
1596			sparseDF:                  make(map[string]int, len(sparseQuery.terms)),
1597			sparsePrecomputedFiles:    make(map[string]bool),
1598			allFiles:                  append([]string(nil), source.paths...),
1599			termPostings:              newSearchTermPostings(),
1600			// A resolved commit is what says "this is a Git repository", so a needle the posting lists
1601			// cannot price can be answered exactly by one `git grep`. An empty treeish means the working
1602			// tree, which is what a worktree search indexes; a HEAD search must grep the commit itself.
1603			gitGrepUsable: source.commit != "",
1604		}
1605		if !options.Worktree {
1606			selection.gitGrepTreeish = source.commit
1607		}
1608		// Interactive committed-tree search can ask Git's optimized object-store
1609		// scanner for every eligible content match in one fixed-string batch. Keep
1610		// every matched/path-evidenced file: MaxIndexedFiles is a cold selective-
1611		// indexing guard, not a retrieval recall cap once the graph is preindexed.
1612		// Deeper sparse search retains the exhaustive path until corpus statistics
1613		// can be persisted with the preindex.
1614		//
1615		// Tree identity is what makes the preindexed graph exact for source's
1616		// current HEAD; the grep below runs against source.commit directly, so a
1617		// same-tree preindex built at a different commit is still an exact match.
1618		exactFullPreindex := preindexCacheHit &&
1619			preindexedSnapshot.Header.Tree == source.tree
1620		grepPatterns, grepSafe := searchGitGrepPatterns(q.terms)
1621		if exactFullPreindex && !options.Worktree && !options.Deep && grepSafe {
1622			matches, grepErr := gitutil.GrepTreePaths(ctx, source.absRepo, source.commit, grepPatterns)
1623			if grepErr == nil {
1624				selection.files = committedSearchFiles(source.paths, matches, q)
1625				selection.sparseFiles = append([]string(nil), selection.files...)
1626				selection.preselectionBackend = "git-tree-grep"
1627				selection.preselectionPasses = 1
1628				selection.preselectionFilesExamined = len(source.paths)
1629				// This path never reads content, so there are no posting lists. Git answered once, so
1630				// it can answer again for a single needle.
1631				selection.gitGrepUsable = true
1632				selection.gitGrepTreeish = source.commit
1633				return selection, nil
1634			}
1635		}
1636		if options.IndexAllFiles || len(source.paths) <= options.MaxIndexedFiles {
1637			selection.files = append([]string(nil), source.paths...)
1638			return selection, nil
1639		}
1640		// Which terms any file matches is not known until the scan is done, so the coverage
1641		// share of every file score is added afterwards, over the matched terms only
1642		// (applySearchFileCoverage). Until then a file carries its matched weight unnormalized.
1643		matchedAnywhere := make([]bool, len(q.terms))
1644		matcher := newSearchTermMatcher(q.terms)
1645		scanPaths := source.paths
1646		usedGitIndexPreselection := false
1647		if shouldUseGitGrepPreselection(options.Worktree, len(source.paths)) {
1648			matches, grepErr := gitutil.GrepIndexMatches(ctx, source.absRepo, searchGitGrepPreselectionPatterns(q), 32)
1649			tracked, trackedErr := gitutil.ListIndexFiles(ctx, source.absRepo)
1650			if grepErr == nil && trackedErr == nil {
1651				usedGitIndexPreselection = true
1652				allowed := make(map[string]bool, len(source.paths))
1653				for _, filePath := range source.paths {
1654					allowed[filePath] = true
1655				}
1656				trackedSet := make(map[string]bool, len(tracked))
1657				for _, filePath := range tracked {
1658					trackedSet[filePath] = true
1659				}
1660				termMatches := make(map[string][]bool)
1661				for _, match := range matches {
1662					if !allowed[match.Path] {
1663						continue
1664					}
1665					seen := termMatches[match.Path]
1666					if seen == nil {
1667						seen = make([]bool, len(q.terms))
1668					}
1669					for index, matched := range matcher.match(match.Text) {
1670						seen[index] = seen[index] || matched
1671					}
1672					termMatches[match.Path] = seen
1673				}
1674				provisional := make([]searchFileCandidate, 0, len(termMatches)+16)
1675				grepMatchedAnywhere := make([]bool, len(q.terms))
1676				for filePath, seen := range termMatches {
1677					matchedWeight := 0.0
1678					for index, matched := range seen {
1679						if matched {
1680							matchedWeight += q.weights[q.terms[index]]
1681							grepMatchedAnywhere[index] = true
1682						}
1683					}
1684					pathScore := pathSearchScore(q, filePath)
1685					provisional = append(provisional, searchFileCandidate{
1686						path:          filePath,
1687						score:         2*pathScore + matchedWeight + searchPathPrior(q, filePath),
1688						matchedWeight: matchedWeight,
1689					})
1690				}
1691				untracked := make([]string, 0, 16)
1692				for _, filePath := range source.paths {
1693					if !trackedSet[filePath] {
1694						untracked = append(untracked, filePath)
1695						continue
1696					}
1697					if _, exists := termMatches[filePath]; !exists {
1698						if pathScore := pathSearchScore(q, filePath); pathScore > 0 {
1699							provisional = append(provisional, searchFileCandidate{
1700								path:  filePath,
1701								score: 2*pathScore + searchPathPrior(q, filePath),
1702							})
1703						}
1704					}
1705				}
1706				applySearchFileCoverage(provisional, q, grepMatchedAnywhere)
1707				sort.Slice(provisional, func(i, j int) bool {
1708					if provisional[i].score != provisional[j].score {
1709						return provisional[i].score > provisional[j].score
1710					}
1711					return provisional[i].path < provisional[j].path
1712				})
1713				poolLimit := len(provisional)
1714				if threshold := (len(provisional)-1)/4 + 1; options.MaxIndexedFiles < threshold {
1715					poolLimit = options.MaxIndexedFiles * 4
1716				}
1717				scanPaths = make([]string, 0, poolLimit+len(untracked))
1718				selection.sparseFiles = make([]string, 0, len(provisional)+len(untracked))
1719				for _, candidate := range provisional {
1720					selection.sparseFiles = append(selection.sparseFiles, candidate.path)
1721				}
1722				selection.sparseFiles = append(selection.sparseFiles, untracked...)
1723				for _, candidate := range provisional[:poolLimit] {
1724					scanPaths = append(scanPaths, candidate.path)
1725				}
1726				scanPaths = append(scanPaths, untracked...)
1727				if len(scanPaths) == 0 {
1728					scanPaths = source.paths
1729				}
1730			}
1731		}
1732		var sparseMu sync.Mutex
1733		var contentReadMu sync.Mutex
1734		var matchedMu sync.Mutex
1735		contentReads := 0
1736		scoreFile := func(filePath string) (searchFileCandidate, bool) {
1737			if err := ctx.Err(); err != nil {
1738				return searchFileCandidate{}, false
1739			}
1740			content, ok := source.read(filePath)
1741			if ok {
1742				contentReadMu.Lock()
1743				contentReads++
1744				contentReadMu.Unlock()
1745			}
1746			if !ok || strings.IndexByte(content, 0) >= 0 {
1747				return searchFileCandidate{}, false
1748			}
1749			if options.Deep && len(sparseQuery.terms) > 0 && len(content) <= maxSparseSearchFileBytes {
1750				lines := strings.Split(strings.TrimSuffix(content, "\n"), "\n")
1751				if len(lines) > 1 || lines[0] != "" {
1752					language := ""
1753					if spec, detected := languageForContent(filePath, content); detected {
1754						language = spec.language
1755					}
1756					fileSparse, documentCount, documentLength := sparseCandidatesForFile(
1757						sparseQuery, filePath, language, lines, options,
1758					)
1759					sparseMu.Lock()
1760					selection.sparseCandidates = append(selection.sparseCandidates, fileSparse...)
1761					selection.sparseDocumentCount += documentCount
1762					selection.sparseDocumentLength += documentLength
1763					selection.sparseFilesContentRead++
1764					selection.sparsePrecomputedFiles[filePath] = true
1765					for _, candidate := range fileSparse {
1766						for term := range candidate.termCounts {
1767							selection.sparseDF[term]++
1768						}
1769					}
1770					sparseMu.Unlock()
1771				}
1772			}
1773			pathScore := pathSearchScore(q, filePath)
1774			matchedWeight := 0.0
1775			matched := matcher.match(content)
1776			for index, hit := range matched {
1777				if hit {
1778					matchedWeight += q.weights[q.terms[index]]
1779				}
1780			}
1781			if pathScore == 0 && matchedWeight == 0 {
1782				return searchFileCandidate{}, false
1783			}
1784			matchedMu.Lock()
1785			for index, hit := range matched {
1786				matchedAnywhere[index] = matchedAnywhere[index] || hit
1787			}
1788			matchedMu.Unlock()
1789			// The posting lists are a by-product of a match this loop already computed. Recording them
1790			// here is what makes a repository-wide literal lookup free later on.
1791			selection.termPostings.record(filePath, matched, q.terms)
1792			return searchFileCandidate{
1793				path:          filePath,
1794				score:         2*pathScore + matchedWeight + searchPathPrior(q, filePath),
1795				matchedWeight: matchedWeight,
1796			}, true
1797		}
1798		workers := 1
1799		if options.Worktree {
1800			workers = minInt(8, maxInt(1, runtime.GOMAXPROCS(0)))
1801		}
1802		files := scoreSearchPaths(ctx, scanPaths, workers, scoreFile)
1803		if err := ctx.Err(); err != nil {
1804			return searchFileSelection{}, err
1805		}
1806		applySearchFileCoverage(files, q, matchedAnywhere)
1807		sort.Slice(files, func(i, j int) bool {
1808			if files[i].score != files[j].score {
1809				return files[i].score > files[j].score
1810			}
1811			return files[i].path < files[j].path
1812		})
1813		if len(files) > options.MaxIndexedFiles {
1814			files = files[:options.MaxIndexedFiles]
1815		}
1816		selected := make([]string, len(files))
1817		for i, file := range files {
1818			selected[i] = file.path
1819		}
1820		selection.files = selected
1821		selection.filesContentRead = contentReads
1822		selection.preselectionBackend = "go-content"
1823		selection.preselectionPasses = 1
1824		selection.preselectionFilesExamined = len(scanPaths)
1825		if usedGitIndexPreselection {
1826			selection.preselectionBackend = "git-index-grep+go-content"
1827			selection.preselectionPasses++
1828			selection.preselectionFilesExamined += len(source.paths)
1829			// The content pass ran over a Git-narrowed pool, so the posting lists cover only part of
1830			// the corpus. Discard them rather than let a block compute a repository-wide total from a
1831			// subset — Git is here, so the exact answer is one grep away.
1832			selection.termPostings = newSearchTermPostings()
1833			selection.gitGrepUsable = true
1834			selection.gitGrepTreeish = ""
1835		}
1836		return selection, nil
1837	}
