2546	func scoreSearchCandidates(candidates []searchCandidate, q searchQuery, fileDF map[string]int, fileCount int) {
2547		if len(candidates) == 0 {
2548			return
2549		}
2550		averageLength := 0.0
2551		for _, candidate := range candidates {
2552			averageLength += float64(maxInt(1, candidate.docLength))
2553		}
2554		averageLength /= float64(len(candidates))
2555		queryWeight := 0.0
2556		idf := make(map[string]float64, len(q.terms))
2557		for _, term := range q.terms {
2558			df := fileDF[term]
2559			weight := math.Log(1+(float64(fileCount-df)+0.5)/(float64(df)+0.5)) * q.weights[term]
2560			idf[term] = weight
2561			if df == 0 {
2562				// No indexed file contains this term, so no candidate can ever match it —
2563				// and, being maximally rare, it would carry the LARGEST idf of the query.
2564				// Charging it to the query weight would put full coverage out of reach and
2565				// tax every document that matched the rest of the query, purely because the
2566				// caller wrote one word the repository has never heard of. An unmatched term
2567				// contributes zero (BM25), never a penalty.
2568				continue
2569			}
2570			queryWeight += weight
2571		}
2572		for i := range candidates {
2573			candidate := &candidates[i]
2574			bm25 := 0.0
2575			coveredWeight := 0.0
2576			codeTokenBonus := 0.0
2577			for _, term := range q.terms {
2578				frequency := candidate.termCounts[term]
2579				if frequency == 0 {
2580					continue
2581				}
2582				weight := idf[term]
2583				coveredWeight += weight
2584				if q.weights[term] >= 2 {
2585					codeTokenBonus += 6 * q.weights[term]
2586				}
2587				denominator := float64(frequency) + 1.2*(0.25+0.75*float64(maxInt(1, candidate.docLength))/averageLength)
2588				bm25 += weight * (float64(frequency) * 2.2 / denominator)
2589			}
2590			// Data declarations (fields/constants) are near-degenerate BM25 docs: a
2591			// one-line declaration that repeats the query identifier outscores the
2592			// method whose body actually misbehaves (a caller's `private final Foo
2593			// foo;` outranking `Foo.go()`'s error handler). The declaration names
2594			// the thing; the defect lives in executable code — damp text evidence
2595			// from data declarations rather than banning them outright. Exception:
2596			// when the query is ABOUT this declaration — its name covers most of
2597			// the query's terms (definition-lookup intent) — the declaration is
2598			// the target, not a bystander.
2599			if searchKindClass(candidate.result.Kind) == searchKindData &&
2600				candidate.result.EndLine-candidate.result.StartLine <= 3 &&
2601				!searchResultHasSignal(candidate.result, "exact-symbol") &&
2602				!searchNameCoversQuery(candidate.result, q) {
2603				bm25 *= 0.4
2604				codeTokenBonus *= 0.5
2605			}
2606			coverage := 0.0
2607			if queryWeight > 0 {
2608				coverage = coveredWeight / queryWeight
2609			}
2610			candidate.score = candidate.baseScore + bm25 + 7*coverage + minFloat64(24, codeTokenBonus)
2611			// trail 18's kind/subject/dotted-call structural bonuses (orthogonal to the
2612			// caller-degree boost that trail 10 applies as a separate step). Centrality was
2613			// dropped in the merge: trail 10's caller-boost is the reviewed successor of the
2614			// same inbound-degree signal, so keeping both would double-count it.
2615			candidate.score += searchStructuralAdjustment(candidate, q)
2616			if codeTokenBonus > 0 {
2617				candidate.result.Signals = appendUnique(candidate.result.Signals, "exact-code-token")
2618			}
2619			if coverage == 1 {
2620				candidate.score += 2
2621				candidate.result.Signals = appendUnique(candidate.result.Signals, "all-query-terms")
2622			}
2623		}
2624	}
2625	
2626	// searchNameCoversQuery reports whether the symbol's own name path matches at
2627	// least half of the query's terms — the signature of a query that is about the
2628	// symbol itself (find/define intent) rather than one that merely mentions it.
2629	func searchNameCoversQuery(result SearchResult, q searchQuery) bool {
2630		name := strings.ToLower(result.QualifiedName)
2631		if name == "" {
2632			name = strings.ToLower(result.SymbolName)
2633		}
2634		if name == "" || len(q.terms) == 0 {
2635			return false
2636		}
2637		matched := 0
2638		for _, term := range q.terms {
2639			if strings.Contains(name, term) {
2640				matched++
2641			}
2642		}
2643		return float64(matched) >= 0.5*float64(len(q.terms))
2644	}
2645	
2646	func searchResultHasSignal(result SearchResult, signal string) bool {
2647		for _, s := range result.Signals {
2648			if s == signal {
2649				return true
2650			}
2651		}
2652		return false
2653	}
2654	
2655	type searchKindClassValue int
2656	
2657	const (
2658		searchKindOther searchKindClassValue = iota
2659		searchKindExec
2660		searchKindData
2661		searchKindContainer
2662	)
2663	
2664	func searchKindClass(kind string) searchKindClassValue {
2665		switch kind {
2666		case "function", "method", "constructor":
2667			return searchKindExec
2668		case "field", "constant", "variable", "property":
2669			return searchKindData
2670		case "class", "struct", "interface", "trait", "enum", "record", "object", "protocol", "module", "type":
2671			return searchKindContainer
2672		}
2673		return searchKindOther
2674	}
2675	
2676	// searchStructuralAdjustment tilts ranking toward the code an agent edits.
2677	// Three effects, each grounded in an observed retrieval failure:
2678	//   - executable definitions outrank everything else at equal text evidence
2679	//     (the fix for "X misbehaves" is in X's code, not in references to X);
2680	//   - container chunks yield to their members: a class-spanning region absorbs
2681	//     its members' matched text and then suppresses the member candidate via
2682	//     overlap dedup, anchoring agents at class heads/constructors instead of
2683	//     the method carrying the signal;
2684	//   - symbols the query names directly (identifier-like terms matching the
2685	//     qualified name path) outrank incidental body matches — issues name
2686	//     their subject far more reliably than they describe its mechanism.
2687	func searchStructuralAdjustment(candidate *searchCandidate, q searchQuery) float64 {
2688		adjustment := 0.0
2689		switch searchKindClass(candidate.result.Kind) {
2690		case searchKindExec:
2691			adjustment += 3
2692		case searchKindContainer:
2693			adjustment -= 3
2694		}
2695		// Subject bonus: when the symbol's own name covers most of the query, the
2696		// query is about this symbol (find/define intent) — any kind wins that.
2697		if searchNameCoversQuery(candidate.result, q) {
2698			adjustment += 4
2699		}
2700		qualified := strings.ToLower(candidate.result.QualifiedName)
2701		if qualified == "" {
2702			qualified = strings.ToLower(candidate.result.SymbolName)
2703		}
2704		if qualified != "" {
2705			matched := 0
2706			for _, term := range q.terms {
2707				if q.weights[term] >= 2 && strings.Contains(qualified, term) {
2708					matched++
2709				}
2710			}
2711			switch {
2712			case matched >= 2:
2713				adjustment += 8
2714			case matched == 1:
2715				adjustment += 2
2716			}
2717			// A dotted call mention in the query ("Type.method(...)") names the
2718			// fix site outright; the named symbol must not lose to neighbors whose
2719			// bodies merely repeat the query's data words.
2720			for _, call := range q.dottedCallMentions {
2721				if strings.HasSuffix(qualified, call) {
2722					adjustment += 15
2723					break
2724				}
2725			}
2726		}
2727		return adjustment
2728	}
2729	
2730	func minFloat64(left, right float64) float64 {
2731		if left < right {
2732			return left
2733		}
2734		return right
2735	}

4359	func pathSearchScore(q searchQuery, filePath string) float64 {
4360		lower := strings.ToLower(filepath.ToSlash(filePath))
4361		base := strings.ToLower(filepath.Base(filePath))
4362		score := 0.0
4363		for _, term := range q.terms {
4364			weight := q.weights[term]
4365			if weight != 1 && weight < 1.25 {
4366				continue
4367			}
4368			if strings.Contains(base, term) {
4369				score += 2.5 * weight
4370			} else if strings.Contains(lower, term) {
4371				score += 1.25 * weight
4372			}
4373		}
4374		return score
4375	}
4376	
4377	func searchPathPrior(q searchQuery, filePath string) float64 {
4378		lower := "/" + strings.ToLower(filepath.ToSlash(filePath))
4379		score := 0.0
4380		if strings.Contains(lower, "/src/") || strings.Contains(lower, "/include/") || strings.Contains(lower, "/lib/") || strings.Contains(lower, "/packages/") {
4381			score += 0.5
4382		}
4383		if strings.Contains(lower, "/.github/workflows/") && !searchQuerySupplied(q, "workflow", "pipeline", "ci", "action") {
4384			score -= 6
4385		}
4386		// .github/ metadata (ISSUE_TEMPLATE, PULL_REQUEST_TEMPLATE, CONTRIBUTING, FUNDING, etc.)
4387		// is NEVER a code fix site, yet issue-template prose matches the problem statement's own
4388		// filled-in fields (version/expected/actual boilerplate) and body-BM25-outranks the real
4389		// source (measured: briannesbitt .github/ISSUE_TEMPLATE.md ranked #1 over src/Carbon/*).
4390		// Hard-demote all non-workflow .github/ paths so template prose can never top the list.
4391		if strings.Contains(lower, "/.github/") && !strings.Contains(lower, "/.github/workflows/") {
4392			score -= 12
4393		}
4394		if strings.Contains(lower, "/dependencies/") || strings.Contains(lower, "/third_party/") || strings.Contains(lower, "/third-party/") {
4395			score -= 5
4396		}
4397		// "regression"/"regressions" are deliberately NOT test-intent words. In issue prose
4398		// "a regression" names behaviour that used to work, not a request for the regression
4399		// suite; a caller who does want tests writes "test"/"spec"/"fixture", and the phrase
4400		// "regression test" already contains "test". Keeping them here let the commonest word
4401		// in a bug report switch off the test demotion for the whole query.
4402		if searchTestArtifactPath(lower) && !searchQuerySupplied(q, searchTestIntentWords...) {
4403			// Strong demotion (was -1.5 — far too weak): a test file that exercises the buggy
4404			// function matches the issue's exact code tokens (function name + behaviour keywords),
4405			// so it out-scores the real source at ~26-47 while the implementation sits at ~13.
4406			// A bug-fix task never edits a test, so tests are pure exploration noise. -12 reliably
4407			// sinks the test below the editable source (measured: briannesbitt RoundTest.php crowded
4408			// out src/Carbon/Traits/Rounding.php; php-cs-fixer's 13 test files buried the fix). Not
4409			// excluded outright — a test still surfaces if it is the only match.
4410			score -= 12
4411		}
