#!/usr/bin/env python3
"""CORRECTED: separate `entire graph <verb>` tool calls from genuine shell exploration,
and split both by phase (before/after first Edit|Write). Read-only."""
import json, os, re, glob, collections, statistics

S = os.path.expanduser("~/work/graphmark/agentic-swebench")
PROJ = os.path.expanduser("~/.claude/projects")
tx = {}
for f in glob.glob(f"{PROJ}/**/*.jsonl", recursive=True):
    tx.setdefault(os.path.basename(f)[:-6], []).append(f)

# a graph invocation, in any of its spellings
GRAPH = re.compile(r'(?:^|[;&|]\s*|\s)(?:entire\s+graph|eg-q(?:\.run)?|\./eg-q|entire-graph)\s+(\w+)')
SHELL_EXPLORE = re.compile(r'(?:^|[;&|]\s*)\s*(?:sudo\s+|time\s+|env\s+\S+=\S+\s+)*(grep|egrep|fgrep|rg|ag|ack|find|locate|cat|head|tail|sed|awk|ls)\b')
BUILDLIKE = re.compile(r'\b(make|cmake|go\s+(build|test|vet)|cargo|mvn|gradle|npm|npx|pnpm|yarn|pytest|phpunit|composer|bundle|rake|rspec|ctest|javac|tsc|jest|vitest|runtest|\./configure)\b')

def strip_graph(cmd):
    """remove every `entire graph ...` segment so its args don't look like shell exploration"""
    return GRAPH.sub(' __GRAPHCALL__ ', cmd)

def scan(arm):
    base = f"{S}/results/REP50_r1_{arm}/{arm}"
    per = []
    for iid in sorted(os.listdir(base)):
        d = f"{base}/{iid}"; cc = f"{d}/cc_out.json"
        if not os.path.exists(cc) or os.path.getsize(cc) == 0: continue
        sid = (json.load(open(cc)) or {}).get("session_id")
        r = collections.Counter(); phase = 0
        for f in tx.get(sid or "", []):
            for line in open(f, errors="replace"):
                try: o = json.loads(line)
                except Exception: continue
                m = o.get("message") or {}
                for b in (m.get("content") or []) if isinstance(m.get("content"), list) else []:
                    if not isinstance(b, dict) or b.get("type") != "tool_use": continue
                    nm = b.get("name"); inp = b.get("input") or {}
                    if nm in ("Edit","MultiEdit","Write","NotebookEdit"):
                        r["edit"] += 1; phase = 1; continue
                    if nm == "Read":
                        r["read"] += 1; r["read_post" if phase else "read_pre"] += 1; continue
                    if nm != "Bash": continue
                    cmd = inp.get("command") or ""
                    gcalls = GRAPH.findall(cmd)
                    if gcalls:
                        for v in gcalls:
                            r["graph"] += 1; r[f"graph_{v}"] += 1
                            r["graph_post" if phase else "graph_pre"] += 1
                    rest = strip_graph(cmd)
                    if BUILDLIKE.search(rest):
                        r["build"] += 1; r["build_post" if phase else "build_pre"] += 1
                    elif SHELL_EXPLORE.search(rest):
                        r["shell"] += 1; r["shell_post" if phase else "shell_pre"] += 1
                    elif not gcalls:
                        r["other"] += 1
        per.append(r)
    return per

out = {}
for arm in ("baseline","eg"):
    per = scan(arm); out[arm] = per
    T = collections.Counter()
    for p in per: T.update(p)
    n = len(per)
    print(f"\n===== {arm.upper()}  (n={n} sessions) =====")
    print(f"  SHELL EXPLORATION  total {T['shell']:>4}   pre-edit {T['shell_pre']:>4}   post-edit {T['shell_post']:>4}   "
          f"({100*T['shell_post']/max(1,T['shell']):.0f}% post)")
    print(f"  BUILD/TEST runs    total {T['build']:>4}   pre-edit {T['build_pre']:>4}   post-edit {T['build_post']:>4}   "
          f"({100*T['build_post']/max(1,T['build']):.0f}% post)")
    print(f"  READ               total {T['read']:>4}   pre-edit {T['read_pre']:>4}   post-edit {T['read_post']:>4}")
    print(f"  EDIT/WRITE         total {T['edit']:>4}")
    print(f"  GRAPH CALLS        total {T['graph']:>4}   pre-edit {T['graph_pre']:>4}   post-edit {T['graph_post']:>4}")
    if T['graph']:
        vb = {k[6:]: v for k, v in T.items() if k.startswith("graph_") and k not in ("graph_pre","graph_post")}
        print(f"    verbs: {vb}")
    print(f"  other bash         {T['other']:>4}")
    print(f"  per session: shell {T['shell']/n:.1f}  build {T['build']/n:.1f}  read {T['read']/n:.1f}  "
          f"edit {T['edit']/n:.1f}  graph {T['graph']/n:.2f}")

B = collections.Counter(); E = collections.Counter()
for p in out["baseline"]: B.update(p)
for p in out["eg"]: E.update(p)
print("\n===== EG vs BASELINE — the displacement question =====")
for k, lab in [("shell","shell exploration"),("build","build/test runs"),("read","Read calls"),("edit","edits")]:
    b, e = B[k], E[k]
    print(f"  {lab:<20} {b:>5} -> {e:>5}   {100*(1-e/max(1,b)):+6.1f}%  ({'ELIMINATED' if e<b else 'ADDED'})")
print(f"  shell PRE-edit       {B['shell_pre']:>5} -> {E['shell_pre']:>5}   {100*(1-E['shell_pre']/max(1,B['shell_pre'])):+6.1f}%")
print(f"  shell POST-edit      {B['shell_post']:>5} -> {E['shell_post']:>5}   {100*(1-E['shell_post']/max(1,B['shell_post'])):+6.1f}%")
print(f"\n  displacement ratio: {(B['shell']-E['shell'])/max(1,E['graph']):.2f} shell calls removed per graph call")

#!/usr/bin/env python3
"""GATE 1b: size the improvised-repro-harness pool in the POST-EDIT phase, both arms.
This is the class a good VERIFY command is supposed to pre-empt. Read-only."""
import json, os, re, glob, collections

S = os.path.expanduser("~/work/graphmark/agentic-swebench")
PROJ = os.path.expanduser("~/.claude/projects")
tx = {}
for f in glob.glob(f"{PROJ}/**/*.jsonl", recursive=True):
    tx.setdefault(os.path.basename(f)[:-6], []).append(f)

GRAPH = re.compile(r'(?:^|[;&|]\s*|\s)(?:entire\s+graph|eg-q(?:\.run)?|entire-graph)\s+\w+')
# writing a scratch file, or running one
SCRATCH_WRITE = re.compile(r"(cat\s*>|tee\s+|printf[^|]*>|echo[^|]*>)\s*[^\s>]*(/tmp/|repro|scratch|check|edge|test_|tmp\.|\.mjs|\.cjs)", re.I)
SCRATCH_RUN   = re.compile(r"\b(node|python3?|ruby|php|go run|cargo run|java|\./a\.out|g\+\+|gcc|clang\+\+|javac)\b[^|;]*(/tmp/|repro|scratch|edge\.|tmp\.|check\.)", re.I)
TMPDIR        = re.compile(r"(mkdir\s+-p\s+/tmp/|cd\s+/tmp/|rm\s+-[rf]+\s+/tmp/)", re.I)
REAL_SUITE    = re.compile(r'\b(pytest|go test|cargo test|mvn|gradle|npm (run )?test|npx (jest|vitest|mocha)|phpunit|rspec|rake test|ctest|make (test|check)|\./runtest|bundle exec)\b', re.I)

def scan(arm):
    base = f"{S}/results/REP50_r1_{arm}/{arm}"
    c = collections.Counter(); ex = collections.defaultdict(list); sess_with = set()
    for iid in sorted(os.listdir(base)):
        cc = f"{base}/{iid}/cc_out.json"
        if not os.path.exists(cc) or os.path.getsize(cc) == 0: continue
        sid = (json.load(open(cc)) or {}).get("session_id")
        phase = 0
        for f in tx.get(sid or "", []):
            for line in open(f, errors="replace"):
                try: o = json.loads(line)
                except Exception: continue
                m = o.get("message") or {}
                for b in (m.get("content") or []) if isinstance(m.get("content"), list) else []:
                    if not isinstance(b, dict) or b.get("type") != "tool_use": continue
                    nm = b.get("name")
                    if nm in ("Edit","MultiEdit","Write","NotebookEdit"):
                        phase = 1; continue
                    if nm == "Write":
                        continue
                    if nm != "Bash": continue
                    cmd = (b.get("input") or {}).get("command") or ""
                    if GRAPH.search(cmd): continue
                    ph = "post" if phase else "pre"
                    hit = None
                    if SCRATCH_WRITE.search(cmd): hit = "write_scratch_harness"
                    elif SCRATCH_RUN.search(cmd): hit = "run_scratch_harness"
                    elif TMPDIR.search(cmd):      hit = "scratch_dir_admin"
                    elif REAL_SUITE.search(cmd):  hit = "run_REAL_suite"
                    if hit:
                        c[f"{ph}:{hit}"] += 1
                        if hit != "run_REAL_suite": sess_with.add(iid)
                        if len(ex[hit]) < 3: ex[hit].append(cmd.replace("\n"," ")[:110])
    return c, ex, sess_with

print(f"{'':<26}{'BASELINE':>10}{'EG':>10}")
res = {}
for arm in ("baseline","eg"):
    res[arm] = scan(arm)
keys = ["post:write_scratch_harness","post:run_scratch_harness","post:scratch_dir_admin","post:run_REAL_suite",
        "pre:write_scratch_harness","pre:run_scratch_harness","pre:scratch_dir_admin","pre:run_REAL_suite"]
for k in keys:
    print(f"  {k:<24}{res['baseline'][0][k]:>10}{res['eg'][0][k]:>10}")
for arm in ("baseline","eg"):
    c = res[arm][0]
    improv = c["post:write_scratch_harness"]+c["post:run_scratch_harness"]+c["post:scratch_dir_admin"]
    real   = c["post:run_REAL_suite"]
    print(f"\n  {arm.upper()}: post-edit improvised-harness calls = {improv}  ({improv/49:.1f}/session)   "
          f"real-suite runs = {real} ({real/49:.1f}/session)")
    print(f"        sessions that improvised at all: {len(res[arm][2])}/49")
print("\nsamples (eg):")
for k, v in res['eg'][1].items():
