tuned = set()
for n in TUNED: tuned |= xids(f"{S}/.elig_{n}.txt")

# HARD BURN 3 — cells whose identities were read per-instance
for t in ["rep50","rep50_run","g1","g2","g3","fab82","rep30_tasks"]:
    tuned |= tids(f"{S}/tasks/{t}.json")

burned = (ran | tuned) & pool
clean = pool - burned
print(f"pool                     : {len(pool)}")
print(f"  executed (results dir) : {len(ran & pool)}")
print(f"  tuned-on / declared    : {len(tuned & pool)}")
print(f"  union burned           : {len(burned)}")
print(f"  CLEAN                  : {len(clean)}")

have = set()
gd = f"{S}/graphs"
if os.path.isdir(gd):
    have = {i for i in os.listdir(gd)
            if os.path.exists(f"{gd}/{i}/graph.edges.ndjson") or os.path.exists(f"{gd}/{i}/graph.symbols.ndjson")}
ready = clean & have
print(f"  CLEAN and graph-ready  : {len(ready)}")

meta = {}
d = json.load(open(f"{S}/tasks/multilingual_300.json"))
for r in (d["instances"] if isinstance(d, dict) else d):
    if isinstance(r, dict): meta[r["instance_id"]] = r.get("language") or r.get("lang") or "?"
print(f"\nlanguage mix CLEAN+READY : {dict(collections.Counter(meta.get(i,'?') for i in ready).most_common())}")
print(f"language mix CLEAN       : {dict(collections.Counter(meta.get(i,'?') for i in clean).most_common())}")
print(f"\nclean+ready ids ({len(ready)}):")
for i in sorted(ready): print(f"   {i}  [{meta.get(i,'?')}]")
json.dump({"clean_ready": sorted(ready), "clean": sorted(clean)}, open("/tmp/holdout2.json","w"), indent=1)
print("\nwrote /tmp/holdout2.json")

