#!/usr/bin/env python3
"""PE1 final population: two pre-specified strata.
  A (pristine) : never run, never tuned-on, not in a nested gate cell
  B (set-exposed): never RUN, but a member of a set that informed config
Primary = A+B. Secondary = A alone. Divergence between them IS the contamination signal."""
import json, os, glob, collections, math

S = os.path.expanduser("~/work/graphmark/agentic-swebench")
def xids(p): return {l.strip() for l in open(p) if l.strip()} if os.path.exists(p) else set()
def tids(p):
    if not os.path.exists(p): return set()
    d = json.load(open(p))
    if isinstance(d, dict) and "instances" in d: return {x["instance_id"] for x in d["instances"]}
    if isinstance(d, list): return {x if isinstance(x, str) else x.get("instance_id") for x in d}
    return set()

universe = tids(f"{S}/tasks/multilingual_300.json")
ran = {os.path.basename(d) for d in glob.glob(f"{S}/results/*/*/*") if os.path.isdir(d)}
nested = set()
for n in ["gate_5","gate_10","gate_20","gate_30","gate_60"]: nested |= xids(f"{S}/.elig_{n}.txt")
tuned = set()
for n in ["val30","h30","hk30","ho5","ho10","ho20","screen6","f5","o10","s20","fb5","op10","sn20","ties","tier"]:
    tuned |= xids(f"{S}/.elig_{n}.txt")
for t in ["rep50","rep50_run","g1","g2","g3","rep30_tasks","fab82"]: tuned |= tids(f"{S}/tasks/{t}.json")

have = set()
gd = f"{S}/graphs"
if os.path.isdir(gd):
    have = {i for i in os.listdir(gd)
            if os.path.exists(f"{gd}/{i}/graph.edges.ndjson") or os.path.exists(f"{gd}/{i}/graph.symbols.ndjson")}

never_run = (universe - ran) & have
A = never_run - nested - tuned                 # pristine
B = never_run & (nested | tuned)               # never run, but set-level exposed
meta = {}
d = json.load(open(f"{S}/tasks/multilingual_300.json"))
for r in (d["instances"] if isinstance(d, dict) else d):
    if isinstance(r, dict): meta[r["instance_id"]] = r.get("language") or r.get("lang") or "?"
def lang(s): return dict(collections.Counter(meta.get(i,"?") for i in s).most_common())

print(f"universe (multilingual_300)      : {len(universe)}")
print(f"  ever run (any result dir)      : {len(ran & universe)}")
print(f"  NEVER RUN and graph-ready      : {len(never_run)}")
print(f"\nSTRATUM A  pristine              : {len(A)}   {lang(A)}")
print(f"STRATUM B  set-exposed, never run: {len(B)}   {lang(B)}")
print(f"PRIMARY    A+B                   : {len(A|B)}   {lang(A|B)}")

print("\npower (sd from this project's own five cells: usd 0.34, tok 0.43 in log space)")
for n_, tag in ((len(A), "A only"), (len(A|B), "A+B primary")):
    if not n_: continue
    for lbl, sd in (("usd", 0.34), ("tok", 0.43)):
        print(f"  n={n_:<4} ({tag:<11}) {lbl}: CI +/-{1.96*sd/math.sqrt(n_)*100:.1f}pp   MDE(80%) {2.80*sd/math.sqrt(n_)*100:.1f}%")

open("/tmp/PE1-A.txt","w").write("\n".join(sorted(A))+"\n")
open("/tmp/PE1-primary.txt","w").write("\n".join(sorted(A|B))+"\n")
json.dump({"A":sorted(A),"B":sorted(B),"primary":sorted(A|B),
           "lang_A":lang(A),"lang_primary":lang(A|B)}, open("/tmp/PE1-strata.json","w"), indent=1)
print(f"\nwrote /tmp/PE1-A.txt ({len(A)}) and /tmp/PE1-primary.txt ({len(A|B)})")

