// TotalSymbols and RiskTotal are left intact so the notice states what was withheld.
func applyPosteditWideChangeGate(response posteditResponse) posteditResponse {
	if len(response.Files) < posteditWideChangeFiles {
		return response
	}
	response.WideChangeSuppressed = len(response.Files)
	response.Symbols = nil
	response.Risks = nil
	return response
}

