#!/usr/bin/env python3
"""TARGET SESSION SHAPE: search -> read -> edit -> impact -> edit -> verify -> done = ~7 turns.
Actual: 55.3. What are the other 48 doing, and has ANY session in this cell come close?
Reproduce-proven-results: find the shortest successful sessions and read what they did. READ-ONLY."""
import json, os, glob, statistics, collections, math

S = os.path.expanduser("~/work/graphmark/agentic-swebench")
PROJ = os.path.expanduser("~/.claude/projects")
tx = {}
for f in glob.glob(f"{PROJ}/**/*.jsonl", recursive=True):
    tx.setdefault(os.path.basename(f)[:-6], []).append(f)

EDIT = {"Edit","MultiEdit","Write","NotebookEdit"}
BUILDRX = ("make","cmake","cargo","mvn","gradle","npm","npx","pnpm","yarn","pytest","phpunit",
           "composer","bundle","rake","rspec","ctest","javac","tsc","jest","vitest","runtest",
           "go build","go test","go vet","tox","nose")
EXPLORE = ("grep","egrep","rg","find","locate","cat ","head ","tail ","sed -n","awk","ls ")

def toks(cc):
    mu=cc.get("modelUsage") or {}
    if mu:
        t=sum((m.get(k,0) or 0) for m in mu.values() for k in
              ("inputTokens","outputTokens","cacheReadInputTokens","cacheCreationInputTokens"))
        if t: return t
    u=cc.get("usage") or {}
    return sum(u.get(k,0) or 0 for k in ("input_tokens","output_tokens","cache_read_input_tokens","cache_creation_input_tokens"))

def classify(sid):
    """bucket every tool call in the session"""
    c = collections.Counter(); seq = []
    for f in tx.get(sid or "", []):
        for line in open(f, errors="replace"):
            try: o = json.loads(line)
            except Exception: continue
            m = o.get("message") or {}; body = m.get("content")
            if not isinstance(body, list): continue
            for b in body:
                if not isinstance(b, dict) or b.get("type") != "tool_use": continue
                nm = b.get("name")
                if nm in EDIT: c["edit"] += 1; seq.append("E"); continue
                if nm == "Read": c["read"] += 1; seq.append("R"); continue
                if nm in ("Grep","Glob"): c["explore"] += 1; seq.append("x"); continue
                if nm != "Bash": c["other"] += 1; seq.append("o"); continue
                cmd = (b.get("input") or {}).get("command") or ""
                if ("entire graph" in cmd) or ("eg-q" in cmd): c["graph"] += 1; seq.append("G")
                elif any(k in cmd for k in BUILDRX):          c["build"] += 1; seq.append("B")
                elif any(k in cmd for k in EXPLORE):          c["explore"] += 1; seq.append("x")
                else:                                          c["other"] += 1; seq.append("o")
    return c, "".join(seq)

def arm(a):
    base = f"{S}/results/REP50_r1_{a}/{a}"; o = {}
    for i in sorted(os.listdir(base)):
        if i.startswith('.'): continue
        cc = f"{base}/{i}/cc_out.json"; pf = f"{base}/{i}/patch.diff"
        if not os.path.exists(cc) or not os.path.getsize(cc): continue
        try: j = json.load(open(cc))
        except Exception: continue
        c, seq = classify(j.get("session_id"))
        o[i] = dict(tok=toks(j), usd=j.get("total_cost_usd") or 0, turns=j.get("num_turns") or 0,
                    patch=os.path.getsize(pf) if os.path.exists(pf) else 0, c=c, seq=seq,
                    calls=sum(c.values()))
    return o

B, E = arm("baseline"), arm("eg")
ids = [i for i in sorted(set(B)&set(E)) if B[i]["usd"]>0 and E[i]["usd"]>0 and B[i]["patch"] and E[i]["patch"]]

print("=== WHERE THE 55 TURNS GO (per session, mean over 49) ===")
print(f"{'bucket':<10} {'eg':>7} {'base':>7} {'delta':>7}   what a 7-turn session allows")
budget = {"graph":2, "read":1, "edit":2, "build":1, "explore":0, "other":1}
tot_e = tot_b = 0
for k in ("graph","explore","read","edit","build","other"):
    me = sum(E[i]["c"][k] for i in ids)/len(ids); mb = sum(B[i]["c"][k] for i in ids)/len(ids)
    tot_e += me; tot_b += mb
    print(f"{k:<10} {me:>7.1f} {mb:>7.1f} {me-mb:>+7.1f}   {budget[k]:>3}")
print(f"{'TOTAL':<10} {tot_e:>7.1f} {tot_b:>7.1f} {tot_e-tot_b:>+7.1f}   {sum(budget.values()):>3}")

print("\n=== HAS ANY SESSION COME CLOSE? shortest SUCCESSFUL sessions (both arms) ===")
allses = [("eg", i, E[i]) for i in ids] + [("base", i, B[i]) for i in ids]
allses.sort(key=lambda r: r[2]["calls"])
print(f"{'arm':<5} {'instance':<34} {'calls':>5} {'turns':>5} {'tokens':>11}  sequence (G=graph B=build x=explore R=read E=edit)")
for a, i, r in allses[:12]:
    print(f"{a:<5} {i[:34]:<34} {r['calls']:>5} {r['turns']:>5} {r['tok']:>11,}  {r['seq'][:60]}")

print("\n=== THE FLOOR: what does the CHEAPEST QUARTILE look like vs the most expensive? ===")
eg_sorted = sorted(ids, key=lambda i: E[i]["calls"])
for lab, grp in (("cheapest 12 eg sessions", eg_sorted[:12]), ("dearest 12 eg sessions", eg_sorted[-12:])):
    print(f"  {lab}")
    for k in ("graph","explore","read","edit","build","other"):
        print(f"     {k:<9} {sum(E[i]['c'][k] for i in grp)/len(grp):>6.1f}")
    se=sum(E[i]['tok'] for i in grp); sb=sum(B[i]['tok'] for i in grp)
    print(f"     pooled vs baseline on these: {100*(1-se/sb):+.1f}%")

print("\n=== WHAT 7 TURNS WOULD BE WORTH (elasticity 1.682) ===")
te = sum(E[i]["turns"] for i in ids)/len(ids)
for target in (7, 12, 20, 30, 40, 50.6):
    print(f"  eg at {target:>4.1f} turns/session -> tokens x{(target/te)**1.682:.3f}  "
          f"= {100*(1-(target/te)**1.682*sum(E[i]['tok'] for i in ids)/sum(B[i]['tok'] for i in ids)):+6.1f}% vs baseline")

print("\n=== THE IRREDUCIBLE PART: how many EDITS does the gold patch actually need? ===")
files = []
for i in ids:
    pf = f"{S}/results/REP50_r1_baseline/baseline/{i}/patch.diff"
    n = 0
    try:
        for line in open(pf, errors="replace"):
            if line.startswith("+++ "): n += 1
    except Exception: pass
    files.append(n)
print(f"  baseline patch files: median {statistics.median(files):.0f}, mean {statistics.mean(files):.1f}, max {max(files)}")
print(f"  a session touching {statistics.median(files):.0f} file(s) needs ~{statistics.median(files):.0f} edit turns.")
print(f"  eg actually makes {sum(E[i]['c']['edit'] for i in ids)/len(ids):.1f} edit calls/session.")

