#!/usr/bin/env python3
"""Is the low per-call rate a VERB-MIX problem? search is never degenerate; grep is 46% junk and
is the most-used verb. If search-heavy sessions have a materially higher elimination rate, the
lever is 'route lexical queries to search' — a pure tool change, no prompt, no fairness exposure.
READ-ONLY."""
import json, os, glob, math, collections, statistics

S = os.path.expanduser("~/work/graphmark/agentic-swebench")
PROJ = os.path.expanduser("~/.claude/projects")
tx = {}
for f in glob.glob(f"{PROJ}/**/*.jsonl", recursive=True):
    tx.setdefault(os.path.basename(f)[:-6], []).append(f)

def toks(cc):
    mu=cc.get("modelUsage") or {}
    if mu:
        t=sum((m.get(k,0) or 0) for m in mu.values() for k in
              ("inputTokens","outputTokens","cacheReadInputTokens","cacheCreationInputTokens"))
        if t: return t
    u=cc.get("usage") or {}
    return sum(u.get(k,0) or 0 for k in ("input_tokens","output_tokens","cache_read_input_tokens","cache_creation_input_tokens"))

VERBS = ("search","impact","neighbors","callers","changed","def","grep","symbols","edges")

def scan(sid):
    g=collections.Counter(); nong=0; pairs=[]
    for f in tx.get(sid or "", []):
        lines=list(open(f,errors="replace"))
        for idx,line in enumerate(lines):
            try: o=json.loads(line)
            except Exception: continue
            m=o.get("message") or {}; body=m.get("content")
            if not isinstance(body,list): continue
            for b in body:
                if not isinstance(b,dict) or b.get("type")!="tool_use": continue
                nm=b.get("name")
                cmd=((b.get("input") or {}).get("command") or "") if nm=="Bash" else ""
                if ("entire graph" in cmd) or ("eg-q" in cmd):
                    v="?"
                    for cand in VERBS:
                        if f" {cand}" in cmd: v=cand; break
                    g[v]+=1; pairs.append((b.get("id"),v,cmd[:120]))
                else: nong+=1
    return g,nong,pairs

def results(sid):
    """map tool_use_id -> result text, so we can judge degeneracy from the ACTUAL answer"""
    out={}
    for f in tx.get(sid or "", []):
        for line in open(f,errors="replace"):
            try: o=json.loads(line)
            except Exception: continue
            m=o.get("message") or {}; body=m.get("content")
            if not isinstance(body,list): continue
            for b in body:
                if isinstance(b,dict) and b.get("type")=="tool_result":
                    c=b.get("content")
                    s=c if isinstance(c,str) else json.dumps(c)
                    out[b.get("tool_use_id")]=s
    return out

def arm(a):
    base=f"{S}/results/REP50_r1_{a}/{a}"; o={}
    for i in sorted(os.listdir(base)):
        if i.startswith('.'): continue
        cc=f"{base}/{i}/cc_out.json"; pf=f"{base}/{i}/patch.diff"
        if not os.path.exists(cc) or not os.path.getsize(cc): continue
        try: j=json.load(open(cc))
        except Exception: continue
        sid=j.get("session_id"); g,nong,pairs=scan(sid)
        o[i]=dict(tok=toks(j),usd=j.get("total_cost_usd") or 0,turns=j.get("num_turns") or 0,
                  patch=os.path.getsize(pf) if os.path.exists(pf) else 0,
                  g=g,gtot=sum(g.values()),nong=nong,pairs=pairs,sid=sid)
    return o

B,E=arm("baseline"),arm("eg")
ids=[i for i in sorted(set(B)&set(E)) if B[i]["usd"]>0 and E[i]["usd"]>0 and B[i]["patch"] and E[i]["patch"]]

DEG=("no symbol named","0 matches","(no matches","pattern too broad","grep failed",
     "no results","not found in the graph","no definition")
print("=== DEGENERACY MEASURED FROM THE ACTUAL TOOL RESULT (not the .payload sidecar) ===")
