        dist=collections.Counter(min(l,6) for l in lens)
        print(f"            length histogram  " + "  ".join(f"{k}{'+' if k==6 else ''}:{dist[k]}" for k in sorted(dist)))
        print(f"            calls sitting in bursts of >=2 : {sum(l for l in lens if l>=2)}/{tot} "
