import json, os, glob

NEW=os.path.expanduser("~/pe1/graphmark/agentic-swebench")
OLD=os.path.expanduser("~/work/graphmark/agentic-swebench")

def toks(cc):
    mu=cc.get("modelUsage") or {}
    if mu:
        t=sum((m.get(k,0) or 0) for m in mu.values() for k in
              ("inputTokens","outputTokens","cacheReadInputTokens","cacheCreationInputTokens"))
        if t: return t
    u=cc.get("usage") or {}
    return sum(u.get(k,0) or 0 for k in ("input_tokens","output_tokens",
               "cache_read_input_tokens","cache_creation_input_tokens"))

def read(p):
    f=f"{p}/cc_out.json"
    if not (os.path.exists(f) and os.path.getsize(f)>1): return None
    try: j=json.load(open(f))
    except Exception: return None
    return dict(tok=toks(j),turns=j.get("num_turns") or 0,usd=j.get("total_cost_usd") or 0,
                sub=j.get("subtype"))

def load(root,tag,arm):
    base=f"{root}/results/{tag}_r1_{arm}/{arm}"; o={}
    if not os.path.isdir(base): return o
    for i in os.listdir(base):
        if i.startswith('.'): continue
        r=read(f"{base}/{i}")
        pf=f"{base}/{i}/patch.diff"
        if r and r["usd"]>0 and os.path.exists(pf) and os.path.getsize(pf): o[i]=r
    return o

NE,NB=load(NEW,"R50FIX","eg"),load(NEW,"R50FIX","baseline")
OE,OB=load(OLD,"REP50","eg"),load(OLD,"REP50","baseline")
g=sorted(set(NE)&set(NB))
se=sum(NE[i]["tok"] for i in g); sb=sum(NB[i]["tok"] for i in g)
print(f"current n={len(g)}  eg {se:,}  base {sb:,}  = {100*(1-se/sb):+.2f}%\n")

TAIL=["sharkdp__bat-1892","redis__redis-11510"]
print("=== what the censored attempt DID capture (archived) ===")
half={}
for i in TAIL:
    for arm,d in (("eg",NEW+f"/results/R50FIX_r1_eg/eg"),("baseline",NEW+f"/results/R50FIX_r1_baseline/baseline")):
        for p in glob.glob(f"{d}/.{i}.capped1800.*"):
            r=read(p)
            if r:
                half[(i,arm)]=r
                print(f"  {i.split('__')[-1]:<14} {arm:<9} {r['tok']:>11,} tok  {r['turns']:>3}t  ${r['usd']:.2f}  {r['sub']}")
print()
print("=== REP50 reference for the same two ===")
for i in TAIL:
    if i in OE and i in OB:
        print(f"  {i.split('__')[-1]:<14} eg {OE[i]['tok']:>11,}  base {OB[i]['tok']:>11,}  "
              f"= {100*(1-OE[i]['tok']/OB[i]['tok']):+7.1f}%")

print("\n=== SCENARIOS for the final n=50 ===")
def scenario(lab, pairs):
    e=se+sum(a for a,b in pairs); b=sb+sum(b for a,b in pairs)
    print(f"  {lab:<46} {100*(1-e/b):+7.2f}%   (delta {100*(1-e/b)-100*(1-se/sb):+.2f}pt)")

# 1. they repeat REP50 ratios, scaled by this cell's baseline inflation on the 48
infl_num=sum(NB[i]["tok"] for i in g if i in OB); infl_den=sum(OB[i]["tok"] for i in g if i in OB)
infl=infl_num/infl_den if infl_den else 1.0
print(f"  (baseline inflation on the measured 48: x{infl:.2f})")
p=[]
for i in TAIL:
    if i in OE and i in OB:
        b=OB[i]["tok"]*infl; p.append((b*(OE[i]["tok"]/OB[i]["tok"]), b))
scenario("both repeat their REP50 ratio", p)

# 2. use the captured half where we have it, REP50 ratio for the missing half
p=[]
for i in TAIL:
    if (i,"eg") in half and i in OE and i in OB:
        e=half[(i,"eg")]["tok"]; p.append((e, e/(OE[i]["tok"]/OB[i]["tok"])))
    elif (i,"baseline") in half and i in OE and i in OB:
        b=half[(i,"baseline")]["tok"]; p.append((b*(OE[i]["tok"]/OB[i]["tok"]), b))
scenario("captured half + REP50 ratio for the other", p)

# 3. both neutral
p=[]
for i in TAIL:
    if i in OB: b=OB[i]["tok"]*infl; p.append((b,b))
scenario("both land neutral (0%)", p)

# 4. both win 30%
p=[]
for i in TAIL:
    if i in OB: b=OB[i]["tok"]*infl; p.append((b*0.7,b))
scenario("both win +30%", p)
print("""
READ: bat-1892 lost -79.8% and redis-11510 won +68.4% in REP50 — they pull in OPPOSITE directions,
