BUILD = re.compile(r'\b(mvn|gradle|gradlew|cargo|go test|go build|npm|yarn|pnpm|pytest|tox|make|ctest|cmake|composer|bundle|rake|phpunit|jest|mocha|dotnet|swift)\b')
SEARCH = re.compile(r'\b(grep|rg|ag|ack|find|fd|ls|locate)\b')
READ = re.compile(r'\b(cat|head|tail|less|more|sed -n|awk)\b')
GIT = re.compile(r'\bgit\b')
GRAPHC = re.compile(r'(entire[- ]graph|eg-q|graph search|graph impact|graph neighbors)')

def classify(name, inp):
    blob = json.dumps(inp)[:4000] if inp else ""
    if name in ("Grep", "Glob"):
        return "search"
    if name == "Read":
        return "read"
    if name in ("Edit", "MultiEdit", "NotebookEdit"):
        return "edit"
    if name == "Write":
        p = (inp or {}).get("file_path", "") or ""
        return "scratch" if ("/tmp" in p or "scratch" in p or "repro" in p.lower()) else "edit"
    if name in ("TodoWrite", "Task", "WebFetch", "WebSearch"):
        return "other"
    if name == "Bash":
        c = (inp or {}).get("command", "") or ""
        if GRAPHC.search(c):
            return "graph"
        if BUILD.search(c):
            return "build"
        if SEARCH.search(c):
            return "search"
        if READ.search(c):
            return "read"
        if GIT.search(c):
            return "git"
        if re.search(r'\b(cd|mkdir|cp|mv|rm|chmod|export|echo|pwd|which|env)\b', c):
            return "shell"
        return "other"
    if GRAPHC.search(name) or GRAPHC.search(blob):
        return "graph"
    return "other"

def sessions(arm):
    base = f"{S}/results/{CELL}_r1_{arm}/ccfg/projects"
    out = []
    for f in glob.glob(f"{base}/*/*.jsonl"):
        calls = []
        try:
            for line in open(f, errors="ignore"):
                line = line.strip()
                if not line:
                    continue
                try:
                    j = json.loads(line)
                except Exception:
                    continue
                if j.get("type") != "assistant":
                    continue
                msg = j.get("message") or {}
                for c in (msg.get("content") or []):
                    if isinstance(c, dict) and c.get("type") == "tool_use":
                        calls.append((c.get("name", "?"), c.get("input") or {}))
        except Exception:
            continue
        if calls:
            out.append(calls)
    return out

print(f"{CELL}: decomposing tool calls per session")
print()
rows = {}
for arm in ("eg", "baseline"):
    ss = sessions(arm)
    if not ss:
        print(f"  {arm}: no transcripts found"); continue
    tot = collections.Counter()
    pre = collections.Counter()
    post = collections.Counter()
    n_edits, spans = [], []
    for calls in ss:
        cats = [classify(n, i) for n, i in calls]
        first_edit = next((k for k, c in enumerate(cats) if c == "edit"), None)
        last_edit = max((k for k, c in enumerate(cats) if c == "edit"), default=None)
        for k, c in enumerate(cats):
            tot[c] += 1
            if first_edit is None or k < first_edit:
                pre[c] += 1
            else:
                post[c] += 1
        n_edits.append(sum(1 for c in cats if c == "edit"))
        if first_edit is not None and last_edit is not None:
            spans.append(last_edit - first_edit)
    N = len(ss)
    rows[arm] = (N, tot, pre, post, n_edits, spans)
    print(f"  === {arm}  (n={N} sessions, {sum(tot.values())} tool calls, "
          f"{sum(tot.values())/N:.1f}/session) ===")
    print(f"    {'category':<10}{'total':>8}{'/sess':>8}{'pre-edit':>10}{'post-edit':>11}{'% of all':>10}")
    for c, v in tot.most_common():
        print(f"    {c:<10}{v:>8}{v/N:>8.1f}{pre[c]:>10}{post[c]:>11}{100*v/sum(tot.values()):>9.1f}%")
    print(f"    edits/session {statistics.mean(n_edits):.1f}   "
          f"first->last edit span {statistics.mean(spans) if spans else 0:.1f} calls   "
          f"sessions with 0 edits {sum(1 for x in n_edits if x==0)}/{N}")
    print()

if "eg" in rows and "baseline" in rows:
    (Ne, te, pe, poe, _, _) = rows["eg"]
    (Nb, tb, pb, pob, _, _) = rows["baseline"]
    print("  === eg MINUS baseline, per session (negative = eg removes calls) ===")
    print(f"    {'category':<10}{'eg/sess':>9}{'base/sess':>11}{'delta':>9}{'pre':>8}{'post':>8}")
    allc = set(te) | set(tb)
    tot_d = 0
    for c in sorted(allc, key=lambda c: -(abs(te[c]/Ne - tb[c]/Nb))):
        d = te[c]/Ne - tb[c]/Nb
        tot_d += d
        print(f"    {c:<10}{te[c]/Ne:>9.2f}{tb[c]/Nb:>11.2f}{d:>+9.2f}{pe[c]/Ne-pb[c]/Nb:>+8.2f}{poe[c]/Ne-pob[c]/Nb:>+8.2f}")
    print(f"    {'TOTAL':<10}{sum(te.values())/Ne:>9.2f}{sum(tb.values())/Nb:>11.2f}{tot_d:>+9.2f}")
    print()
    print("  === the 7-turn ideal: how far is a session from find->edit->verify? ===")
    ideal = 7
    print(f"    eg       {sum(te.values())/Ne:>6.1f} calls/session  = {sum(te.values())/Ne/ideal:.1f}x the 7-call ideal")
    print(f"    baseline {sum(tb.values())/Nb:>6.1f} calls/session  = {sum(tb.values())/Nb/ideal:.1f}x")
    print(f"    biggest removable pools (eg arm, calls/session):")
    for c, v in te.most_common(5):
        if c != "edit":
            print(f"      {c:<10}{v/Ne:>6.2f}/sess   would be {100*(v/Ne)/(sum(te.values())/Ne):.0f}% of the session if removed")

#!/usr/bin/env python3
"""After the graph answers, what does the agent search for?
(a) symbols the graph never mentioned   -> capability gap
(b) symbols the graph DID return        -> redundant verification (behaviour, addressable)
(c) files the graph already named       -> payload sufficient but ignored
Uses gq_calls.log.payload (what the graph returned) + the transcript (what happened next)."""
import json, glob, os, re, sys, collections, statistics
S = os.path.expanduser("~/pe1/graphmark/agentic-swebench")
CELL = sys.argv[1] if len(sys.argv) > 1 else "REP50X"

PATH_RX = re.compile(r'[\w./-]+\.(?:java|py|go|rs|rb|php|js|ts|tsx|jsx|c|cc|cpp|h|hpp|cs|kt|scala|swift|m|mm)\b')
IDENT_RX = re.compile(r'\b[A-Za-z_][A-Za-z0-9_]{3,}\b')
STOP = set('''the and for with that this from into your which when have will been were are was not but
class func function def return type struct impl public private static final void const let var
import package module export default new if else while true false null none self args kwargs
string int bool float list dict map set error err test tests file path name value data result
graph search line lines code file_path symbol symbols match matches found NONE'''.split())

def idents(s):
    return {w for w in IDENT_RX.findall(s or "") if w.lower() not in STOP}

def tool_calls(jsonl):
    out = []
    try:
        for line in open(jsonl, errors="ignore"):
            line = line.strip()
            if not line:
                continue
            try:
                j = json.loads(line)
            except Exception:
                continue
            if j.get("type") != "assistant":
                continue
            for c in ((j.get("message") or {}).get("content") or []):
                if isinstance(c, dict) and c.get("type") == "tool_use":
                    out.append((c.get("name", "?"), c.get("input") or {}))
    except Exception:
        pass
    return out

# map instance -> transcript, by matching the checkout path embedded in the project dir name
def transcripts(arm):
    m = {}
    for f in glob.glob(f"{S}/results/{CELL}_r1_{arm}/ccfg/projects/*/*.jsonl"):
        d = os.path.basename(os.path.dirname(f))
        m.setdefault(d, []).append(f)
    return m

GRAPHC = re.compile(r'(entire[- ]graph|eg-q|graph search|graph impact|graph neighbors)')
SEARCH_TOOLS = ("Grep", "Glob")
SEARCH_CMD = re.compile(r'\b(grep|rg|ag|ack|find|fd)\b')

agg = collections.Counter()
per_session = []
n_used = 0

for inst_dir in sorted(glob.glob(f"{S}/results/{CELL}_r1_eg/eg/*/")):
    iid = os.path.basename(inst_dir.rstrip("/"))
    pay = inst_dir + "gq_calls.log.payload"
    if not (os.path.exists(pay) and os.path.getsize(pay) > 0):
        continue
    blob = open(pay, errors="ignore").read()
    graph_files = {os.path.basename(p) for p in PATH_RX.findall(blob)}
    graph_syms = idents(blob)
    if not graph_syms and not graph_files:
        continue

    # find this instance's transcript: the project dir name contains the instance id
    tf = None
    for d in glob.glob(f"{S}/results/{CELL}_r1_eg/ccfg/projects/*/"):
        if iid.replace("__", "-").replace("_", "-").lower() in os.path.basename(d.rstrip("/")).lower():
            js = glob.glob(d + "*.jsonl")
            if js:
                tf = max(js, key=os.path.getsize)
                break
    if not tf:
        continue
    calls = tool_calls(tf)
    if not calls:
        continue
    n_used += 1

    first_graph = None
    for k, (nm, inp) in enumerate(calls):
        s = nm + " " + json.dumps(inp)[:600]
        if GRAPHC.search(s):
            first_graph = k
            break
    if first_graph is None:
        continue

    b = c = a = 0
    for nm, inp in calls[first_graph + 1:]:
        if nm in SEARCH_TOOLS:
            q = str(inp.get("pattern", "")) + " " + str(inp.get("glob", ""))
        elif nm == "Bash" and SEARCH_CMD.search(str(inp.get("command", ""))):
            q = str(inp.get("command", ""))
        elif nm == "Read":
            p = os.path.basename(str(inp.get("file_path", "")))
            if p and p in graph_files:
                c += 1
            continue
        else:
            continue
        qi = idents(q)
        if qi & graph_syms:
            b += 1
        else:
            a += 1
    agg["b_redundant_search"] += b
    agg["a_new_symbol_search"] += a
    agg["c_read_graph_file"] += c
    per_session.append((b, a, c))

print(f"{CELL}: post-graph behaviour, eg arm  (n={len(per_session)} sessions with a graph call and a transcript)")
if not per_session:
    print("  could not join payloads to transcripts"); raise SystemExit
tb = agg["b_redundant_search"]; ta = agg["a_new_symbol_search"]; tc = agg["c_read_graph_file"]
tot = tb + ta
N = len(per_session)
print()
print(f"  searches issued AFTER the graph answered: {tot}  ({tot/N:.1f}/session)")
print(f"    (b) for a symbol the graph ALREADY returned : {tb:>5}  {100*tb/tot if tot else 0:>5.1f}%   {tb/N:.1f}/sess")
print(f"    (a) for a symbol the graph never mentioned  : {ta:>5}  {100*ta/tot if tot else 0:>5.1f}%   {ta/N:.1f}/sess")
print(f"    (c) Read of a file the graph already named  : {tc:>5}          {tc/N:.1f}/sess")
print()
print(f"  ADDRESSABLE pool (b + c) = {tb+tc} calls = {(tb+tc)/N:.1f}/session")
print(f"  CAPABILITY gap    (a)    = {ta} calls = {ta/N:.1f}/session")
print()
print(f"  interpretation: if (b)+(c) dominate, the payload was sufficient and the agent")
print(f"  re-verified anyway -> a behaviour problem, addressable without new graph verbs.")
print(f"  25% needs -8.3 calls/session; addressable pool is {(tb+tc)/N:.1f}/session.")

