    print(f"  PRECISION = {100*hits/(hits+misses):.1f}%   <- the label claims the change 'usually also lands here'")
    print()
    print("  by outcome band:")
    for b in ("severe <-60%", "mid", "winner >+20%"):
        h, m_ = per_band[b]
        if h + m_:
            print(f"    {b:<14} listed {h+m_:<4} in-gold {h:<3} precision {100*h/(h+m_):>5.1f}%")
    print()
    if hits/(hits+misses) < 0.5:
        print(f"  VERDICT: the claim is FALSE — {100*(1-hits/(hits+misses)):.0f}% of the files it points at are")
        print(f"  NOT touched by the real fix. Presenting them as 'the same change usually also lands here'")
        print(f"  invites exactly the extra edits that Step 0.1 tied to catastrophic loss (p=0.0009).")
    else:
        print("  VERDICT: the claim is broadly supported; RELATED SITES is not the creep driver.")

