#!/usr/bin/env python3
"""SWE-bench Pro ships several text fields as JSON-ENCODED strings: the value starts
with a quote and its newlines are literal backslash-n. Decode them once so the agent
sees real prose. Applied to both arms identically, so this is a fidelity fix, not an
arm-asymmetric one."""
import json, os

S = os.path.expanduser("~/pe1/graphmark/agentic-swebench")
TEXT = ("problem_statement", "pro_interface", "pro_requirements")

def decode(v):
    if not isinstance(v, str):
        return v
    s = v.strip()
    # a doubly-encoded field is a JSON string literal: starts AND ends with a quote
    if len(s) >= 2 and s[0] == '"' and s[-1] == '"':
        try:
            out = json.loads(s)
            if isinstance(out, str):
                return out
        except Exception:
            pass
    # some fields are unquoted but still carry literal \n
    if "\\n" in v and "\n" not in v:
        return v.replace("\\r\\n", "\n").replace("\\n", "\n").replace('\\"', '"')
    return v

for fn in ("swebench_pro_731.json", "pro_pilot5.json"):
    p = f"{S}/tasks/{fn}"
    d = json.load(open(p))
    changed = 0
    for i in d["instances"]:
        for k in TEXT:
            if k in i:
                new = decode(i[k])
                if new != i[k]:
                    i[k] = new; changed += 1
    json.dump(d, open(p, "w"))
    print(f"  {fn}: decoded {changed} fields across {len(d['instances'])} instances")

# verify on the pilot
d = json.load(open(f"{S}/tasks/pro_pilot5.json"))
print("\n  verification:")
for i in d["instances"]:
    ps = i["problem_statement"]
    print(f"    {i['language']:11} len={len(ps):6}  real_newlines={ps.count(chr(10)):4}  "
          f"literal_backslash_n={ps.count(chr(92)+'n'):3}  leading_quote={ps.lstrip()[:1]==chr(34)}")
