GRAPHVERB = re.compile(r'\b(query|search|neighbors|impact|def|explain)\b')
REPOFLAG = re.compile(r'--repo\s+(\S+)')

def tool_events(path):
    try:
        lines = open(path, errors="ignore").read().splitlines()
    except OSError:
        return []
    out = []
    for line in lines:
        if '"tool_use"' not in line and '"tool_result"' not in line:
            continue
        try:
            d = json.loads(line)
        except Exception:
            continue
        c = (d.get("message") or {}).get("content")
        if isinstance(c, list):
            for b in c:
                if isinstance(b, dict) and b.get("type") in ("tool_use", "tool_result"):
                    out.append(b)
    return out

def qualify(root):
    tiers = collections.Counter()
    reasons = collections.Counter()
    for f in glob.glob(os.path.join(root, "*", "*.jsonl")):
        evs = tool_events(f)
        res = {b.get("tool_use_id"): b for b in evs if b.get("type") == "tool_result"}
        for b in evs:
            if b.get("type") != "tool_use":
                continue
            inp = b.get("input") or {}
            cmd = str(inp.get("command", "")) if b.get("name") == "Bash" else ""
            if "graph" not in cmd or not GRAPHVERB.search(cmd):
                continue
            r = res.get(b.get("id"))
            body = ""
            if r:
                con = r.get("content")
                body = con if isinstance(con, str) else " ".join(
                    x.get("text", "") for x in con if isinstance(x, dict))

            has_payload = bool(RANK.search(body))
