            has_revision = bool(re.search(r'\b[0-9a-f]{40}\b', cmd))

            if repo_exists and has_revision:
                tiers["full-execution"] += 1
            elif has_payload:
                tiers["frozen-render"] += 1
            else:
                tiers["neither"] += 1
                if not body:
                    reasons["no recorded result"] += 1
                elif re.search(r'\|\s*(head|jq|python3|wc|tail)\b', cmd):
                    reasons["output piped away before context"] += 1
                else:
                    reasons["result present but no parseable ranking"] += 1
