// markCompleteWhenSnippetCoversSymbol adds complete-symbol to a result whose snippet provably
// contains its whole symbol, and reports whether it did. See the call site in search.go for
// why each guard is load-bearing; in short, the decision is made from LINE BOUNDS, which
// budget truncation keeps honest, and never from byte counts or rendered shape.
func markCompleteWhenSnippetCoversSymbol(result *SearchResult) bool {
	for _, signal := range result.Signals {
		switch signal {
		case searchCompleteSymbolSignal:
			return false // already promised; nothing to add
		case searchFullUnitElidedSignal, searchHeadWindowSignal:
			return false // an explicit statement that the body is partial; never overrule it
		}
	}
	// A one-line symbol is excluded because the single-line budget fallback truncates WITHIN a
	// line while leaving the span at one line, which is the only shape where matching bounds
	// can still describe missing text.
	if result.SymbolStartLine <= 0 || result.SymbolEndLine <= result.SymbolStartLine {
		return false
	}
	if result.SnippetStartLine <= 0 || result.SnippetEndLine < result.SnippetStartLine {
		return false
	}
	if result.SnippetStartLine > result.SymbolStartLine || result.SnippetEndLine < result.SymbolEndLine {
		return false
	}
	if result.Snippet == "" {
		return false
	}
	// The rendered body must actually carry every line the bounds claim, or a dropped line
	// would pass a containment check that only compared numbers.
	if got, want := len(strings.Split(result.Snippet, "\n")), result.SnippetEndLine-result.SnippetStartLine+1; got != want {
		return false
	}
	result.Signals = appendUnique(result.Signals, searchCompleteSymbolSignal)
	return true
}
