def doc_comment(path, start_line, language="Go"):
    """Author-written description immediately above a declaration.

    Go/TS take contiguous // lines; TS also accepts a JSDoc /** ... */ block, which is where
    TypeScript authors actually write. Extending past Go was required to test whether the
    head-to-head result is a Go artifact -- a single-language benchmark cannot tell you that.
    """
    try: lines = open(path, errors="ignore").read().splitlines()
    except OSError: return ""
    out, i = [], start_line - 2
    while i >= 0 and lines[i].strip().startswith("//"):
        out.append(lines[i].strip().lstrip("/").strip()); i -= 1
    if out:
        return " ".join(reversed(out))
    if language in ("TypeScript", "JavaScript", "TSX"):
        j = start_line - 2
        while j >= 0 and not lines[j].strip():
            j -= 1
        if j >= 0 and lines[j].strip().endswith("*/"):
            block = []
            while j >= 0:
                t = lines[j].strip()
                block.append(t.lstrip("/*").rstrip("*/").lstrip("*").strip())
                if t.startswith("/**"): break
                j -= 1
            return " ".join(w for w in reversed(block) if w and not w.startswith("@"))
    return ""

    try:
        fh = open(path, errors="ignore")
    except OSError:
        return out
    for line in fh:
        if '"tool_use"' not in line and '"tool_result"' not in line:
            continue
        try:
            d = json.loads(line)
        except Exception:
            continue
        msg = d.get("message")
        if not isinstance(msg, dict):
            continue
        c = msg.get("content")
        if not isinstance(c, list):
            continue                      # malformed / string content: skip, never raise
        for b in c:
            if isinstance(b, dict) and b.get("type") in ("tool_use", "tool_result"):
                out.append(b)
    return out


def result_text(block):
    if not isinstance(block, dict):
        return ""
    con = block.get("content")
    if isinstance(con, str):
        return con
    if isinstance(con, list):
        # join with newline, not space: space-joined blocks merge adjacent rank lines into
        # one and the ranked-entry count silently halves
        return "\n".join(str(x.get("text", "")) for x in con if isinstance(x, dict))
    return ""


def qualify(root):
    tiers = collections.Counter()
    reasons = collections.Counter()
    # subagent transcripts live in nested dirs; v1's fixed glob depth missed them
    files = sorted(set(glob.glob(os.path.join(root, "**", "*.jsonl"), recursive=True)))
    seen_ids = set()
    for f in files:
        evs = tool_events(f)
        res = {b.get("tool_use_id"): b for b in evs if b.get("type") == "tool_result"}
        for b in evs:
            if b.get("type") != "tool_use" or b.get("name") != "Bash":
