import json, re, sys

S = "/private/tmp/claude-501/-Users-suhaan-devenv/b0108f24-43a4-413e-94c9-bd361b6fafc5/scratchpad"

def words(text):
    return re.findall(r"[a-z0-9]+", text.lower())

def trigrams(ws):
    return set(tuple(ws[i:i+3]) for i in range(len(ws)-2))

def glued(text):
    return re.sub(r"[^a-z0-9]", "", text.lower())

def split_ident(sym):
    # split camelCase / snake_case / digits boundaries
    s = sym.replace("_", " ")
    s = re.sub(r"(?<=[a-z0-9])(?=[A-Z])", " ", s)
    s = re.sub(r"(?<=[A-Z])(?=[A-Z][a-z])", " ", s)
    return s.lower()

def extract_comments_and_strings(src):
    out = []
    for m in re.finditer(r"//(.*)", src):
        out.append(m.group(1))
    for m in re.finditer(r"/\*(.*?)\*/", src, re.S):
        out.append(m.group(1))
    for m in re.finditer(r'"((?:[^"\\]|\\.)*)"', src):
        out.append(m.group(1))
    for m in re.finditer(r'`([^`]*)`', src):
        out.append(m.group(1))
    return " ".join(out)

def get_source(case):
    fp = f"{S}/fx-brain/{case['file']}"
    lo, hi = case["span"]
    with open(fp, errors="replace") as f:
        lines = f.readlines()
    return "".join(lines[lo-1:hi])

def main():
    cases = json.load(open(f"{S}/fresh/cases.json"))["cases"]
    queries = json.load(open(f"{S}/fresh/queries.json"))
    assert len(cases) == len(queries), (len(cases), len(queries))
    violations = []
    for i, (c, q) in enumerate(zip(cases, queries)):
        rq = q["realistic"]
        qwords = words(rq)
        qtri = trigrams(qwords)
        qglued = glued(rq)

        # rule 3
        if c["has_doc"]:
            docwords = words(c.get("doc", ""))
        else:
            src = get_source(c)
            cs = extract_comments_and_strings(src)
            docwords = words(cs)
        doctri = trigrams(docwords)
        overlap = qtri & doctri
        if overlap:
            violations.append((i, c["symbol"], "rule3", sorted(overlap)[:5]))

        # rule 4
        symglued = glued(split_ident(c["symbol"]))
        if symglued and symglued in qglued:
            violations.append((i, c["symbol"], "rule4-glued-symbol-in-query", symglued))
        # also check ident field itself doesn't leak (not required though)

        # word count rule 1 (6-25 words)
        n = len(rq.split())
        if not (6 <= n <= 25):
            violations.append((i, c["symbol"], "rule1-wordcount", n))

    if violations:
        print(f"{len(violations)} VIOLATIONS")
        for v in violations:
            print(v)
        sys.exit(1)
    else:
        print(f"OK: {len(cases)} cases, no violations")

if __name__ == "__main__":
    main()
