#!/usr/bin/env python3
"""Wake this Claude Code session when Codex leaves an unread bridge message.

Runs as an `asyncRewake` command hook on Stop: Stop fires each time the session finishes a turn and
goes idle, the hook waits in the background, and exiting 2 wakes the session with stderr shown as a
system reminder. It only reads the mailbox (SQLite opened read-only), so it never marks anything
read: the session reads its inbox itself, which sets read_at and ends the wake condition.

Scope and safety:
- Acts only for the Claude session the bridge is bound to (SESSIONS["claude"] in bridge.py); any
  other session sharing this project's settings exits 0 at once.
- One waiter per session: a lock directory holding the waiter's pid. A live holder means this
  firing exits 0, so repeated Stop events never stack waiters.
- Bounded: gives up silently after MAX_WAIT seconds (keep it below the hook's configured timeout).
"""
import json
import os
import sqlite3
import sys
import time
from pathlib import Path

DEVENV = Path(__file__).resolve().parents[2]
MAILBOX = DEVENV / ".agent-comms" / "mailbox.sqlite3"
BRIDGE = DEVENV / ".agent-comms" / "bridge.py"
LOCK_ROOT = Path("/tmp/claude-501/bridge-wake")
POLL_SECONDS = 15
MAX_WAIT = 23 * 3600


def bound_session():
    """The Claude session id the bridge is bound to, read from bridge.py's SESSIONS table."""
    for line in BRIDGE.read_text().splitlines():
        line = line.strip()
        if line.startswith('"claude":'):
            return line.split(":", 1)[1].strip().strip(",").strip('"')
    return None


def pid_alive(pid):
    try:
        os.kill(pid, 0)
    except ProcessLookupError:
        return False
    except PermissionError:
        return True
    return True


def take_lock(session):
    LOCK_ROOT.mkdir(parents=True, exist_ok=True)
    lock = LOCK_ROOT / f"{session}.lock"
    for _ in range(2):
        try:
            lock.mkdir()
        except FileExistsError:
            try:
                holder = int((lock / "pid").read_text())
            except (OSError, ValueError):
                holder = 0
            if holder and pid_alive(holder):
                return None
            # Stale lock from a waiter that died: clear it and retry once.
            for child in lock.iterdir():
                child.unlink()
            lock.rmdir()
            continue
        (lock / "pid").write_text(str(os.getpid()))
        return lock
    return None


def unread_from_codex():
    """Unread codex -> claude messages, oldest first, without changing the mailbox."""
    conn = sqlite3.connect(f"file:{MAILBOX}?mode=ro", uri=True, timeout=5)
    try:
        return conn.execute(
            "SELECT seq, id, discussion FROM messages "
            "WHERE sender='codex' AND recipient='claude' AND read_at IS NULL ORDER BY seq"
        ).fetchall()
    finally:
        conn.close()


def main():
    try:
        event = json.load(sys.stdin)
    except (ValueError, OSError):
        return 0
    session = event.get("session_id")
    if not session or session != bound_session():
        return 0
    lock = take_lock(session)
    if lock is None:
        return 0
    try:
        deadline = time.monotonic() + MAX_WAIT
        while time.monotonic() < deadline:
            try:
                unread = unread_from_codex()
            except sqlite3.Error:
                unread = []
            if unread:
                first_seq = unread[0][0]
                ids = ", ".join(f"{seq} {mid}" for seq, mid, _ in unread[:5])
                print(
                    f"Codex left {len(unread)} unread bridge message(s): {ids}. Read them with: "
                    f"python3 .agent-comms/bridge.py --as claude --session {session} inbox "
                    f"--discussion {unread[0][2]} --after {first_seq - 1} --limit 20",
                    file=sys.stderr,
                )
                return 2
            time.sleep(POLL_SECONDS)
        return 0
    finally:
        try:
            (lock / "pid").unlink()
            lock.rmdir()
        except OSError:
            pass


if __name__ == "__main__":
    sys.exit(main())

