#!/usr/bin/env python3
"""Wake this Claude Code session when Codex leaves an unread bridge message.

Runs as an `asyncRewake` command hook on Stop: Stop fires each time the session finishes a turn and
goes idle, the hook waits in the background, and exiting 2 wakes the session with stderr shown as a
system reminder. It only reads the mailbox (SQLite opened read-only), so it never marks anything
read: the session reads its inbox itself, which sets read_at and ends the wake condition.

Scope and safety:
- Acts only for the Claude session the bridge is bound to (SESSIONS["claude"] in bridge.py); any
  other session sharing this project's settings exits 0 at once.
- One waiter per session. The claim is atomic: a private directory holding the waiter's pid is
  renamed onto the lock path, so the pid is present the instant the lock exists. A lock whose holder
  is dead is renamed aside (never deleted in place), so two cleaners cannot remove a fresh claim.
- One wake per new message: the highest seq already announced is remembered per session. A message
  that stays unread is announced again only after REMIND_SECONDS, so repeated Stop events do not
  re-wake the session for the same backlog.
- If the bridge gains a `wake` column, only rows with wake=1 count (older rows default to 0).
- Bounded: gives up silently after MAX_WAIT seconds (keep it below the hook's configured timeout).
"""
import json
import os
import sqlite3
import sys
import time
from pathlib import Path

DEVENV = Path(__file__).resolve().parents[2]
MAILBOX = DEVENV / ".agent-comms" / "mailbox.sqlite3"
BRIDGE = DEVENV / ".agent-comms" / "bridge.py"
LOCK_ROOT = Path("/tmp/claude-501/bridge-wake")
POLL_SECONDS = 15
REMIND_SECONDS = 600
MAX_WAIT = 23 * 3600


def bound_session():
    """The Claude session id the bridge is bound to, read from bridge.py's SESSIONS table."""
    try:
        text = BRIDGE.read_text()
    except OSError:
        return None
    for line in text.splitlines():
        line = line.strip()
        if line.startswith('"claude":'):
            return line.split(":", 1)[1].strip().strip(",").strip('"')
    return None


def pid_alive(pid):
    try:
        os.kill(pid, 0)
    except ProcessLookupError:
        return False
    except PermissionError:
        return True
    return True


def remove_tree(path):
    try:
        for child in path.iterdir():
            child.unlink()
        path.rmdir()
    except OSError:
        pass


def take_lock(session):
    """Atomically claim the per-session waiter lock, or return None if a live waiter holds it."""
    LOCK_ROOT.mkdir(parents=True, exist_ok=True)
    lock = LOCK_ROOT / f"{session}.lock"
    for _ in range(3):
        claim = LOCK_ROOT / f".{session}.claim.{os.getpid()}"
        remove_tree(claim)
        claim.mkdir()
        (claim / "pid").write_text(str(os.getpid()))
        try:
            os.rename(claim, lock)  # fails when lock exists (non-empty directory)
            return lock
        except OSError:
            remove_tree(claim)
        try:
            holder = int((lock / "pid").read_text())
        except (OSError, ValueError):
            return None  # the lock vanished or is unreadable mid-change: let the next Stop retry
        if pid_alive(holder):
            return None
        # Dead holder: move the stale lock aside atomically; only one cleaner can win the rename.
        stale = LOCK_ROOT / f".{session}.stale.{os.getpid()}"
        try:
            os.rename(lock, stale)
        except OSError:
            continue
        remove_tree(stale)
    return None


def unread_from_codex():
    """Unread codex -> claude messages, oldest first, without changing the mailbox."""
    conn = sqlite3.connect(f"file:{MAILBOX}?mode=ro", uri=True, timeout=5)
    try:
        columns = {row[1] for row in conn.execute("PRAGMA table_info(messages)")}
        wake_filter = " AND wake=1" if "wake" in columns else ""
        return conn.execute(
            "SELECT seq, id, discussion FROM messages "
            "WHERE sender='codex' AND recipient='claude' AND read_at IS NULL" + wake_filter +
            " ORDER BY seq"
        ).fetchall()
    finally:
        conn.close()


def load_state(path):
    try:
        state = json.loads(path.read_text())
        return int(state.get("announced_seq", 0)), float(state.get("announced_at", 0))
    except (OSError, ValueError, TypeError, AttributeError):
        return 0, 0.0


def save_state(path, seq):
    tmp = path.with_suffix(f".tmp.{os.getpid()}")
    tmp.write_text(json.dumps({"announced_seq": seq, "announced_at": time.time()}))
    os.replace(tmp, path)


def main():
    try:
        event = json.load(sys.stdin)
    except (ValueError, OSError):
        return 0
    session = event.get("session_id")
    if not session or session != bound_session():
        return 0
    lock = take_lock(session)
    if lock is None:
        return 0
    state_path = LOCK_ROOT / f"{session}.announced.json"
    try:
        deadline = time.monotonic() + MAX_WAIT
        while time.monotonic() < deadline:
            try:
                unread = unread_from_codex()
            except sqlite3.Error:
                unread = []
            if unread:
                announced_seq, announced_at = load_state(state_path)
                newest = unread[-1][0]
                if newest > announced_seq or time.time() - announced_at >= REMIND_SECONDS:
                    save_state(state_path, newest)
                    first_seq = unread[0][0]
                    ids = ", ".join(f"{seq} {mid}" for seq, mid, _ in unread[:5])
                    print(
                        f"Codex left {len(unread)} unread bridge message(s): {ids}. Read them with: "
                        f"python3 .agent-comms/bridge.py --as claude --session {session} inbox "
                        f"--discussion {unread[0][2]} --after {first_seq - 1} --limit 20",
                        file=sys.stderr,
                    )
                    return 2
            time.sleep(POLL_SECONDS)
        return 0
    finally:
        try:
            if int((lock / "pid").read_text()) == os.getpid():
                remove_tree(lock)
        except (OSError, ValueError):
            pass


if __name__ == "__main__":
    sys.exit(main())

