URL_USERINFO = re.compile(r'(?P<scheme>[A-Za-z][A-Za-z0-9+.-]*://)(?P<userinfo>[^/@?#]*)@')


def redact_headers(value):
    """'Name: value' lines; credential-like header values presence-only, others by value."""
    lines = []
    for line in value.splitlines():
        name, separator, content = line.partition(':')
        if separator and CREDENTIAL_HEADER.fullmatch(name.strip()):
