def egress(slot, identity):
    raw = read_regular(slot / 'egress.log')
    bound = ((identity.get('isolation') or {}).get('egress') or {}) if isinstance(identity, dict) else {}
    allow, port, clients = bound.get('allow'), bound.get('port'), bound.get('client_refuse')
    if raw is None:
        return check('fail', 'egress.log missing')
    if not isinstance(allow, list) or type(port) is not int or not isinstance(clients, list):
        return check('unknown', 'identity binds no egress allowlist, client list and port')
    try:
        records = [json.loads(line) for line in raw.decode('utf-8').splitlines() if line.strip()]
    except (ValueError, UnicodeError):
        return check('unknown', 'egress.log unparseable')
    if not records or not all(isinstance(r, dict) for r in records):
        return check('unknown', 'egress.log empty or not records')
    head = records[0]
    if head.get('decision') != 'listening':
        return check('fail', 'first record is not listening: %r' % head.get('decision'))
    if head.get('target') != '127.0.0.1:%d' % port:   # a stale or foreign log names another proxy
        return check('fail', 'listening record %r is not this cell\'s proxy port %d' % (head.get('target'), port))
    # the proxy's own normalisation (egress_proxy.Policy): the listening record must carry exactly the bound lists
    clients = [str(c).strip().lower().lstrip('.') for c in clients if str(c).strip()]
    if head.get('client_refuse') != clients:
        return check('fail', 'listening client_refuse %r is not the identity-bound list %r'
                     % (head.get('client_refuse'), clients))
    if head.get('allow') != sorted({str(a).strip().lower() for a in allow if str(a).strip()}):
        return check('fail', 'listening allow %r is not the identity-bound allowlist %r' % (head.get('allow'), allow))
    fails, unknown, api, upstream = [], [], 0, 0
    for r in records[1:]:
        decision, target = r.get('decision'), str(r.get('target'))
        host = target.rpartition(':')[0].strip('[]').lower()
        if decision == 'allow' and target in allow:
            api += target == API_TARGET
            continue
        if decision == UPSTREAM_FAILED and target in allow:
            upstream += 1   # the allowlisted host was unreachable: a connection failure, not traffic
            continue
        if decision == 'client_refused' and any(host == c or host.endswith('.' + c) for c in clients):
            continue
        if decision in EGRESS_FAIL or decision in ('allow', 'client_refused', UPSTREAM_FAILED):
            fails.append('%s:%s' % (decision, target))
        else:   # a missing or unknown decision value
