#!/usr/bin/env python3
"""Of the lines baseline agents READ from gold files before their first edit (sed -n A,Bp / head / Read offset+limit /
cat), what fraction lie inside the functions the gold patch changes (graph symbols at base)? Low fraction => agents read
much more than the target function, so delivering exactly that function could cut reads. Offline, no model."""
import glob, json, os, re, sys
sys.path.insert(0, '/Users/suhaan/devenv-worktrees/pilot8-artifacts/runtime/locbench')
from coverage import changed_lines
src = open('mechanism.py').read().split('rows = {}')[0]; ns = {}; exec(src, ns)
S, PROJ, tasks = ns['S'], ns['PROJ'], ns['tasks']
def ranges_from(cmd, path, nlines):
    out = []
    for m in re.finditer(r'sed -n [\'"]?(\d+),(\d+)p[\'"]?\s+(\S+)', cmd):
        if m.group(3).endswith(path) or path.endswith(m.group(3)): out.append((int(m.group(1)), int(m.group(2))))
    for m in re.finditer(r'\bcat\s+(\S+)', cmd):
        if m.group(1).endswith(path): out.append((1, nlines))
    return out
tot_read = in_fn = 0; per = []
for NS in ('pilot8L-s55-eg0d92', 'pilot8M-s55-eg0d92'):
    for iid in sorted(d for d in os.listdir(f'{S}/results/{NS}/baseline') if d in tasks):
        ch = changed_lines(tasks[iid]['patch'])
        syms = [json.loads(l) for l in open(f'{S}/graphs/{iid}/graph.symbols.ndjson') if '"record_type":"symbol"' in l]
        fns = {}
        for path, ls in ch.items():
            for s in syms:
                if s['file_path'] == path and s.get('kind') in ('function', 'method', 'constructor') and any(s['start_line'] <= l <= s['end_line'] for l in ls):
                    fns.setdefault(path, []).append((s['start_line'], s['end_line']))
        ident = json.load(open(f'{S}/results/{NS}/baseline/{iid}/identity.json'))
        cid = re.search(r'c-[0-9a-f]{12}', json.dumps(ident)).group(0)
        f = glob.glob(f'{PROJ}/-Users-Shared-p8cells-{cid}-repo/*.jsonl')[0]
        r_t = r_in = 0
        for line in open(f):
            d = json.loads(line); c = (d.get('message') or {}).get('content')
            if d.get('isSidechain') or not isinstance(c, list): continue
            for x in c:
                if x.get('type') != 'tool_use': continue
                inp = x.get('input') or {}
                if x['name'] in ('Edit', 'Write', 'MultiEdit'): break
                for path in ch:
                    rs = []
                    if x['name'] == 'Read' and str(inp.get('file_path', '')).endswith(path):
                        o = int(inp.get('offset') or 1); rs.append((o, o + int(inp.get('limit') or 2000) - 1))
                    elif x['name'] == 'Bash':
                        rs += ranges_from(inp.get('command', ''), path, 5000)
                    for a, b in rs:
                        span = set(range(a, b + 1)); r_t += len(span)
                        r_in += sum(1 for l in span if any(s <= l <= e for s, e in fns.get(path, [])))
        tot_read += r_t; in_fn += r_in; per.append((iid, r_t, r_in))
print(f'gold-file lines read before first edit: {tot_read}; inside the changed functions: {in_fn} ({100*in_fn/max(tot_read,1):.0f}%)')
print('median per-session lines read:', sorted(p[1] for p in per)[len(per)//2], '; sessions reading >2x the changed functions:',
      sum(1 for p in per if p[1] > 2 * max(p[2], 1)), '/', len(per))
EOF
