// todo-live: the todo board, always visible and kept current.
//
// The board is a plain file, .claude/todo-board.json, which Claude edits
// mid-task. This module re-reads it on a timer, so an edit shows up within a
// few seconds without anyone typing /todo. It draws it in two places:
//   - a compact band above the prompt (always on screen), and
//   - a full pane (opens by itself on a wide terminal, or via /todo-live).

import { atom, read, update } from 'claude-code'
import type { Register } from 'claude-code'

import type { Board, Task } from '../types'

const PANE = 'todo-live'
const BOARD_FILE = '.claude/todo-board.json'
const POLL_MS = 3000

const board = atom({ plugin: 'todo-live', key: 'board' } as const, null)
const raw = atom({ plugin: 'todo-live', key: 'raw' } as const, '')
const boardError = atom({ plugin: 'todo-live', key: 'error' } as const, '')
const isBandHidden = atom({ plugin: 'todo-live', key: 'isBandHidden' } as const, false)

// Reading order: what needs someone first.
const ORDER = ['blocked', 'doing', 'todo', 'done'] as const
const MARK: Record<string, string> = { blocked: '!', doing: '>', todo: '·', done: '+' }
const COLOR: Record<string, string | undefined> = { blocked: 'red', doing: 'yellow', todo: undefined, done: 'green' }
const LABEL: Record<string, string> = { blocked: 'blocked', doing: 'in progress', todo: 'queued', done: 'done' }

function tasksOf(value: Board | null): Task[] {
  if (!value || !Array.isArray(value.tasks)) return []
  return value.tasks.filter(t => t && typeof t.title === 'string')
}

function isOnYou(t: Task): boolean {
  return t.owner === 'user' && t.status !== 'done'
}

function tally(tasks: Task[]) {
  const counts = { blocked: 0, doing: 0, todo: 0, done: 0, onYou: 0 }
  for (const t of tasks) {
    if (t.status in counts) (counts as Record<string, number>)[t.status] += 1
    if (isOnYou(t)) counts.onYou += 1
  }
  return counts
}

// Re-read the file; only write the atoms (and so redraw) when the bytes changed.
async function loadBoard($: Parameters<Parameters<Register>[0]>[2] extends never ? any : any): Promise<void> {
  try {
    const text = await $.fs.read(BOARD_FILE)
    if (typeof text !== 'string' || text.trim() === '') {
      await update($, boardError, () => BOARD_FILE + ' is empty')
      return
    }
    if (text === (await read($, raw))) return
    const parsed = JSON.parse(text) as Board
    await update($, raw, () => text)
    await update($, boardError, () => '')
    await update($, board, () => parsed)
  } catch (err: any) {
    // A board that cannot be read says so; it never draws an empty board,
    // because "nothing to do" and "could not look" are different claims.
    // A half-written file mid-edit lands here too and clears on the next tick.
    await update($, boardError, () => String(err?.message || err).slice(0, 200))
  }
}

export const register: Register = on => {
  let ticking = false

  on('session.start', async ($, e, next) => {
    await $.command.register({
      name: 'todo-live',
      description: 'Open the live todo board pane (it also sits above the prompt)',
    })
    await loadBoard($)
    if (!ticking) {
      ticking = true
      $.clock.every(POLL_MS, () => loadBoard($))
    }
    // Opens by itself where the terminal is wide enough to seat it beside the chat.
    void $.ui.open({ id: PANE, title: 'Todo (live)' })
    return next(e)
  })

  // An edit Claude made this turn shows immediately, not only on the next tick.
  on('turn.complete', async ($, e, next) => {
    await loadBoard($)
    return next(e)
  })

  on('command.run', { command: 'todo-live' }, async $ => {
    await update($, isBandHidden, () => false)
    await loadBoard($)
    await $.ui.open({ id: PANE, title: 'Todo (live)', focus: true, closeOnEscape: true })
    return { text: 'Live todo board opened.' }
  })

  // The band: always above the prompt. Counts, then everything on the user,
  // then what is running. Kept short so it never crowds the prompt.
  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    if (e.props.hasSurvey || (await read($, isBandHidden))) return next(e)
    const { Box, Text, Button } = $.ui.resolve(e)
    const err = await read($, boardError)
    const tasks = tasksOf(await read($, board))
    if (tasks.length === 0 && !err) return next(e)

    const width = Math.max(30, Number(e.props.bodyColumns) || 80)
    const budget = Math.max(3, Math.min(9, Number(e.props.maxRows) || 9))
    const t = tally(tasks)

    const head: any[] = [Text({ bold: true, children: ['Todo'] })]
    if (t.onYou > 0) head.push(Text({ color: 'red', bold: true, children: [t.onYou + ' on you'] }))
    if (t.doing > 0) head.push(Text({ color: 'yellow', children: [t.doing + ' running'] }))
    if (t.todo > 0) head.push(Text({ dimColor: true, children: [t.todo + ' queued'] }))
    if (err) head.push(Text({ color: 'red', children: ['(stale: ' + err.slice(0, 60) + ')'] }))
    head.push(Button({ key: 'open', label: 'Open', onPress: () => $.ui.open({ id: PANE, title: 'Todo (live)', focus: true, closeOnEscape: true }) }))
    head.push(Button({ key: 'hide', label: 'Hide', onPress: () => update($, isBandHidden, () => true) }))

    const line = (task: Task, color: string | undefined, mark: string) =>
      Box({
        flexDirection: 'row',
        columnGap: 1,
        children: [
          Text({ color, children: [mark] }),
          Text({ dimColor: true, children: [task.id || ''] }),
          Text({ wrap: 'truncate-end', children: [task.title.slice(0, width)] }),
        ],
      })

    const rows: any[] = []
    const room = budget - 1
    const onYou = tasks.filter(isOnYou)
    // Plan items (P1, P2, ...) lead the running list: that is the current work.
    const running = tasks
      .filter(x => x.status === 'doing' && !isOnYou(x))
      .sort((a, b) => Number(!/^P\d/.test(a.id || '')) - Number(!/^P\d/.test(b.id || '')))
    for (const task of onYou) if (rows.length < room) rows.push(line(task, 'red', '!'))
    for (const task of running) if (rows.length < room) rows.push(line(task, 'yellow', '>'))
    const shown = rows.length
    const left = onYou.length + running.length - shown
    if (left > 0 && rows.length > 0) {
      rows[rows.length - 1] = Text({ dimColor: true, children: ['  … ' + (left + 1) + ' more, /todo-live for all'] })
    }

    return Box({
      flexDirection: 'column',
      children: [Box({ flexDirection: 'row', columnGap: 2, children: head }), ...rows],
    })
  })

  // The pane: the whole board, same reading order as /todo.
  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e) => {
    const { Box, Text } = $.ui.resolve(e)
    const width = Math.max(32, Number((e.props as any)?.bodyColumns) || 60)
    const value = await read($, board)
    const err = await read($, boardError)
    const tasks = tasksOf(value)

    if (tasks.length === 0) {
      return Box({
        flexDirection: 'column',
        children: [
          Text({ bold: true, children: ['Todo (live)'] }),
          Text({ color: err ? 'red' : undefined, dimColor: !err, wrap: 'wrap', children: [err || 'No tasks on the board yet.'] }),
        ],
      })
    }

    const t = tally(tasks)
    const header: any[] = [Text({ bold: true, children: ['Todo (live)'] })]
    if (t.onYou > 0) header.push(Text({ color: 'red', bold: true, children: [t.onYou + ' waiting on you'] }))
    if (t.doing > 0) header.push(Text({ color: 'yellow', children: [t.doing + ' in progress'] }))
    if (t.todo > 0) header.push(Text({ dimColor: true, children: [t.todo + ' queued'] }))
    if (t.done > 0) header.push(Text({ color: 'green', children: [t.done + ' done'] }))

    const rule = (label: string) =>
      Text({ dimColor: true, children: [label + ' ' + '─'.repeat(Math.max(1, width - label.length - 1))] })

    const rows: any[] = []
    for (const status of ORDER) {
      const group = tasks.filter(x => x.status === status)
      if (group.length === 0) continue
      rows.push(rule(LABEL[status] + ' (' + group.length + ')'))
      for (const task of group) {
        rows.push(
          Box({
            flexDirection: 'row',
            columnGap: 1,
            children: [
              Text({ color: COLOR[status], children: [MARK[status] || '·'] }),
              Text({ dimColor: true, children: [task.id || ''] }),
              Text({ bold: status !== 'done', wrap: 'truncate-end', children: [task.title] }),
              ...(isOnYou(task) ? [Text({ color: 'red', children: ['[you]'] })] : []),
              ...(task.source === 'user' ? [Text({ dimColor: true, children: ['(asked)'] })] : []),
            ],
          }),
        )
        if (task.note) rows.push(Text({ dimColor: true, wrap: 'wrap', children: ['    ' + task.note] }))
      }
    }

    return Box({
      flexDirection: 'column',
      children: [
        Box({ flexDirection: 'row', columnGap: 2, children: header }),
        ...(err ? [Text({ color: 'red', wrap: 'wrap', children: ['Last read failed, showing the previous board: ' + err]})] : []),
        Text({ children: [' '] }),
        ...rows,
        Text({ children: [' '] }),
        Text({ dimColor: true, children: [BOARD_FILE + (value?.updated ? '  ·  updated ' + value.updated : '') + '  ·  live, re-read every ' + POLL_MS / 1000 + 's'] }),
      ],
    })
  })
}

