const board = atom({ plugin: 'todo-board', key: 'board' }, null)
const boardError = atom({ plugin: 'todo-board', key: 'error' }, '')
// The band above the prompt can be hidden for the session. Written only from
// the Hide/Show button's onPress (a handler), never from render.
const bandHidden = atom({ plugin: 'todo-board', key: 'bandHidden' }, false)

// The band: the board, always in view above the prompt, without anyone
// typing /todo. Counts first, then every row waiting on the person, then
// what is running. It reads the same atoms as the pane and, like the pane,
// re-reads nothing itself: the clock started in session.start keeps it live.
on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
  if (e.props?.hasSurvey) return next(e)
  const { Box, Text, Button } = $.ui.resolve(e)
  const hidden = await read($, bandHidden)
  const value = await read($, board)
  const err = await read($, boardError)
  const tasks = tasksOf(value)
  if (tasks.length === 0 && !err) return next(e)

  const openButton = Button({
    key: 'todo-open',
    label: 'Open',
    onPress: () => $.ui.open({ id: PANE, title: 'Todo board', focus: true, closeOnEscape: true }),
  })
  if (hidden) {
    const t = tally(tasks)
    return Box({
      flexDirection: 'row',
      columnGap: 2,
      children: [
        Text({ dimColor: true, children: ['todo' + (t.onYou > 0 ? ' · ' + t.onYou + ' on you' : '')] }),
        Button({ key: 'todo-show', label: 'Show', onPress: () => update($, bandHidden, () => false) }),
      ],
    })
  }

  const t = tally(tasks)
  const head = [Text({ bold: true, children: ['Todo'] })]
  if (t.onYou > 0) head.push(Text({ color: 'red', bold: true, children: [t.onYou + ' on you'] }))
  if (t.doing > 0) head.push(Text({ color: 'yellow', children: [t.doing + ' running'] }))
  if (t.todo > 0) head.push(Text({ dimColor: true, children: [t.todo + ' queued'] }))
  // A failed read is said, never hidden: the rows below are the last good board.
  if (err) head.push(Text({ color: 'red', wrap: 'truncate-end', children: ['board unreadable: ' + err.slice(0, 60)] }))
  head.push(openButton)
  head.push(Button({ key: 'todo-hide', label: 'Hide', onPress: () => update($, bandHidden, () => true) }))

  // Rows: on-you first (they are the reason the board exists), then running.
  // The band never takes more than its share of the screen above the prompt.
  const budget = Math.max(2, Math.min(8, Number(e.props?.maxRows) || 8))
  const room = budget - 1
  const onYou = tasks.filter((x) => x.owner === 'user' && x.status !== 'done')
  const running = tasks.filter((x) => x.status === 'doing' && !(x.owner === 'user'))
  const wanted = [...onYou.map((x) => ['!', 'red', x]), ...running.map((x) => ['>', 'yellow', x])]
  const shown = wanted.length > room ? wanted.slice(0, room - 1) : wanted
  const rows = shown.map(([mark, color, task]) =>
    Box({
      flexDirection: 'row',
      columnGap: 1,
      children: [
        Text({ color, children: [mark] }),
        Text({ dimColor: true, children: [task.id || ''] }),
        ...(task.lane ? [Text({ dimColor: true, children: ['[' + task.lane + ']'] })] : []),
        Text({ wrap: 'truncate-end', children: [task.title] }),
      ],
    }),
  )
  if (shown.length < wanted.length) {
    rows.push(Text({ dimColor: true, children: ['  … ' + (wanted.length - shown.length) + ' more · /todo for the whole board'] }))
  }

  return Box({
    flexDirection: 'column',
    children: [Box({ flexDirection: 'row', columnGap: 2, children: head }), ...rows],
  })
})

on('ui.render', { component: 'Pane' }, async ($, e, next) => {
  if (e.requestId !== PANE) return next(e)

  note?: string
  // Which session's work this row is: two Claude sessions share the board
  // (graph and brain), and each edits only its own lane's rows.
  lane?: string
